243	/// Defines the `as_str`/`Display` pair shared by every single-field `String`
244	/// newtype in this crate, regardless of how the rest of the type (fields,
245	/// derives, serde impls) is shaped.
246	macro_rules! string_newtype_display {
247	    ($name:ident) => {
248	        impl $name {
249	            #[doc = concat!("Returns the ", stringify!($name), " as a string slice.")]
250	            pub fn as_str(&self) -> &str {
251	                &self.0
252	            }
253	        }
254	
255	        impl ::std::fmt::Display for $name {
256	            fn fmt(&self, f: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
257	                f.write_str(&self.0)
258	            }
259	        }
260	    };
261	}
