265	/// Defines a plain single-field `String` newtype: the common derive list,
266	/// `#[schemars(with = "String")]`, transparent (unvalidated) serde, `as_str`,
267	/// and `Display`. For newtypes that validate on construction/deserialize
268	/// (e.g. [`TagName`](crate::tag::TagName), [`CommitSha`]), use
269	/// [`string_newtype_display!`] instead and hand-write the rest.
270	macro_rules! string_newtype {
271	    ($(#[$doc:meta])* $name:ident) => {
272	        $(#[$doc])*
273	        #[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
274	        #[schemars(with = "String")]
275	        #[serde(transparent)]
276	        pub struct $name(pub String);
277	
278	        string_newtype_display!($name);
279	    };
280	}
