324	/// A 40-character hex Git commit SHA.
325	#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, JsonSchema)]
326	#[schemars(with = "String")]
327	pub struct CommitSha(String);
328	
329	impl AsRef<str> for CommitSha {
330	    fn as_ref(&self) -> &str {
331	        &self.0
332	    }
333	}
