335	impl CommitSha {
336	    /// Parses a 40-character hexadecimal Git commit SHA, trimming surrounding whitespace.
337	    ///
338	    /// # Errors
339	    ///
340	    /// Returns `Err(ModelError::InvalidCommitSha)` if the trimmed input is not exactly 40 ASCII hex digits.
341	    pub fn parse(s: &str) -> Result<Self, ModelError> {
342	        let trimmed = s.trim();
343	        if trimmed.len() != 40 || !trimmed.chars().all(|c| c.is_ascii_hexdigit()) {
344	            return Err(ModelError::InvalidCommitSha {
345	                raw: s.to_string(),
346	                reason: "must be exactly 40 hexadecimal characters".to_string(),
347	            });
348	        }
349	        Ok(CommitSha(trimmed.to_lowercase()))
350	    }
351	
352	    /// Returns the full 40-character lowercase hex SHA.
353	    pub fn as_str(&self) -> &str {
354	        &self.0
355	    }
356	
357	    /// Returns the first 7 characters of the SHA, matching git's short-ref convention.
358	    pub fn short(&self) -> &str {
359	        &self.0[..7]
360	    }
361	}
