451	    fn resolve_unique_errs_with_all_candidates_on_ambiguity() {
452	        // A bare target name that exists in two ecosystems is exactly the
453	        // polyglot-workspace ambiguity `matches()`'s doc comment warns
454	        // about -- both must be returned, not silently the first one.
455	        let ids = [
456	            PackageId::parse("cargo/foo").unwrap(),
457	            PackageId::parse("npm/foo").unwrap(),
458	        ];
459	        let target = PackageId::parse("foo").unwrap();
460	        let result = target.resolve_unique(ids.iter(), |id| id);
461	        let candidates = result.expect_err("two matches must be Err, not silently the first");
462	        assert_eq!(candidates.len(), 2);
463	        assert!(candidates.contains(&&ids[0]));
