493	    fn package_id_rejects_path_traversal() {
494	        assert!(PackageId::parse("/etc/passwd").is_err(), "must reject leading slashes");
495	
496	        let dotdot_err = PackageId::parse("../../secret").unwrap_err();
497	        assert!(
498	            matches!(dotdot_err, PackageIdParseError::PathTraversal { .. }),
499	            "expected PathTraversal for a genuine `..` traversal, got: {dotdot_err:?}"
500	        );
501	        assert!(
