507	    /// A leading `-` is not path traversal at all (no `..` anywhere in the
508	    /// input) -- it's rejected because it could be misread as a CLI flag by
509	    /// a shelled-out command downstream. The old shared `PathTraversal`
510	    /// variant's message ("contains path traversal `..`") was factually
511	    /// false for this input; it must get its own variant with an accurate
512	    /// message, for the bare form and both prefixed forms.
513	    #[test]
514	    fn package_id_rejects_leading_hyphen_with_accurate_error() {
515	        for input in ["-x", "cargo:-x", "cargo/-x"] {
516	            let err = PackageId::parse(input).unwrap_err();
517	            assert!(
518	                matches!(err, PackageIdParseError::LeadingHyphen { .. }),
519	                "expected LeadingHyphen for `{input}`, got: {err:?}"
520	            );
521	            let msg = err.to_string();
522	            assert!(
523	                !msg.contains(".."),
524	                "LeadingHyphen's message must not falsely claim `..` path traversal, got: {msg}"
525	            );
526	            assert!(
527	                msg.contains('-'),
528	                "LeadingHyphen's message should reference the offending `-`, got: {msg}"
529	            );
530	        }
531	    }
