 31	/// Package identity across ecosystems.
 32	#[derive(Clone, Debug, PartialEq, Eq, Hash, JsonSchema)]
 33	#[schemars(with = "String")]
 34	pub enum PackageId {
 35	    Bare(String),
 36	    Prefixed { ecosystem: Ecosystem, name: String },
 37	}
 38	
 39	impl PackageId {
 40	    /// Parses package identity string.
 41	    ///
 42	    /// # Errors
 43	    ///
 44	    /// Returns `Err` if `s` is empty, starts with `/`, contains `..`, or has a known ecosystem prefix followed by an empty name.
 45	    pub fn parse(s: &str) -> Result<Self, PackageIdParseError> {
 46	        if s.is_empty() {
 47	            return Err(PackageIdParseError::Empty);
 48	        }
 49	        if s.starts_with('/') {
 50	            return Err(PackageIdParseError::LeadingSlash { raw: s.to_string() });
 51	        }
 52	        if s.starts_with('-') {
 53	            return Err(PackageIdParseError::LeadingHyphen { raw: s.to_string() });
 54	        }
 55	        if s.contains("..") {
 56	            return Err(PackageIdParseError::PathTraversal { raw: s.to_string() });
 57	        }
 58	
 59	        if let Some((prefix, remainder)) = s.split_once(':') {
 60	            if let Some(ecosystem) = Ecosystem::from_prefix(prefix) {
 61	                Self::validate_prefixed_remainder(s, prefix, remainder)?;
 62	                return Ok(PackageId::Prefixed {
 63	                    ecosystem,
 64	                    name: remainder.to_string(),
 65	                });
 66	            }
 67	        }
 68	
 69	        if let Some((prefix, remainder)) = s.split_once('/') {
 70	            if let Some(ecosystem) = Ecosystem::from_prefix(prefix) {
 71	                Self::validate_prefixed_remainder(s, prefix, remainder)?;
 72	                return Ok(PackageId::Prefixed {
 73	                    ecosystem,
 74	                    name: remainder.to_string(),
 75	                });
 76	            }
 77	        }
 78	
 79	        Ok(PackageId::Bare(s.to_string()))
 80	    }
 81	
 82	    /// Shared validation for the remainder of an ecosystem-prefixed id (the part
 83	    /// after the `:` or `/` separator), used by both prefixed forms in [`Self::parse`].
 84	    fn validate_prefixed_remainder(raw: &str, prefix: &str, remainder: &str) -> Result<(), PackageIdParseError> {
 85	        if remainder.is_empty() {
 86	            return Err(PackageIdParseError::EmptyNameAfterPrefix {
 87	                raw: raw.to_string(),
 88	                prefix: prefix.to_string(),
 89	            });
 90	        }
 91	        if remainder.starts_with('-') {
 92	            return Err(PackageIdParseError::LeadingHyphen { raw: raw.to_string() });
 93	        }
 94	        if remainder.contains("..") {
 95	            return Err(PackageIdParseError::PathTraversal { raw: raw.to_string() });
 96	        }
 97	        Ok(())
 98	    }
 99	
100	    /// Returns the canonical display form: bare names as-is, prefixed ids as `ecosystem/name`.
101	    pub fn display_name(&self) -> String {
102	        match self {
103	            PackageId::Bare(name) => name.clone(),
104	            PackageId::Prefixed { ecosystem, name } => {
105	                format!("{}/{}", ecosystem.prefix(), name)
106	            }
107	        }
108	    }
109	
110	    /// Returns the ecosystem this id is scoped to, or `None` for a [`PackageId::Bare`] id.
111	    pub fn ecosystem(&self) -> Option<Ecosystem> {
112	        match self {
113	            PackageId::Bare(_) => None,
114	            PackageId::Prefixed { ecosystem, .. } => Some(*ecosystem),
115	        }
116	    }
117	
118	    /// Returns the package name without any ecosystem prefix.
119	    pub fn name(&self) -> &str {
120	        match self {
121	            PackageId::Bare(name) => name,
122	            PackageId::Prefixed { name, .. } => name,
123	        }
124	    }
125	
126	    /// Weak "could be the same package" check, not strict equality.
127	    ///
128	    /// `Bare(x)` matches any `Prefixed(_, x)` (bare is an ecosystem wildcard);
129	    /// `Prefixed(e1, x)` matches `Prefixed(e2, x)` only if `e1 == e2`; exact
130	    /// equality always matches.
131	    ///
132	    /// **Caller contract**: in a polyglot workspace, a bare lookup can match
133	    /// packages in two or more ecosystems (e.g. `foo` in both Cargo and npm).
134	    /// Callers must collect *all* matches and error on 2+ — see
135	    /// `aggregate::resolve_target_package`'s `AmbiguousName` pattern — never
136	    /// take the first match silently. A plain existence check (`.any()`) is
137	    /// safe only because the aggregation layer already rejects ambiguous
138	    /// references upstream.
139	    pub fn matches(&self, other: &Self) -> bool {
140	        if self == other {
141	            return true;
142	        }
143	        if self.name() == other.name() {
144	            match (self.ecosystem(), other.ecosystem()) {
145	                (None, _) | (_, None) => true,
146	                (Some(e1), Some(e2)) => e1 == e2,
147	            }
148	        } else {
149	            false
150	        }
151	    }
152	
153	    /// The single implementation of the collect-and-error pattern
154	    /// [`matches`](Self::matches)'s own doc comment requires every caller
155	    /// to hand-roll: filters `items` down to those whose id (via `id_of`)
156	    /// matches `self`, then resolves the result to exactly one, none, or
157	    /// reports the ambiguity.
158	    ///
159	    /// - `Ok(None)`: no item matches.
160	    /// - `Ok(Some(item))`: exactly one item matches -- the unambiguous case.
161	    /// - `Err(candidates)`: two or more items match. The caller decides how
162	    ///   to report this (e.g. as a domain-specific "ambiguous name" error
163	    ///   naming `self` and `candidates`) -- this method stays generic over
164	    ///   any `T` (a `Package`, a bare `PackageId`, ...) rather than forcing
165	    ///   a particular error type on every layer that needs this check.
166	    pub fn resolve_unique<'a, T>(
167	        &self,
168	        items: impl Iterator<Item = &'a T>,
169	        id_of: impl Fn(&'a T) -> &'a PackageId,
170	    ) -> Result<Option<&'a T>, Vec<&'a T>> {
171	        let matching: Vec<&'a T> = items.filter(|item| id_of(item).matches(self)).collect();
172	        match matching.len() {
173	            0 => Ok(None),
174	            1 => Ok(Some(matching[0])),
175	            _ => Err(matching),
176	        }
177	    }
178	}
