  1	use std::collections::HashSet;
  2	use std::path::{Path, PathBuf};
  3	
  4	use schemars::JsonSchema;
  5	use serde::{Deserialize, Serialize};
  6	
  7	use crate::{
  8	    workspace_relative, Ecosystem, ModelError, PackageId, PackageKey, PublishTarget, ReleaseTrigger, TagTemplate,
  9	    VersionGrammar,
 10	};
 11	
 12	/// A package in the workspace graph.
 13	#[derive(Clone, Debug, PartialEq, Eq)]
 14	pub struct Package {
 15	    pub id: PackageId,
 16	    pub manifests: Vec<ManifestDecl>,
 17	    pub changelog: Option<PathBuf>,
 18	    pub release_trigger: ReleaseTrigger,
 19	    pub publish_to: Vec<PublishTarget>,
 20	    pub tag_template: Option<TagTemplate>,
 21	}
 22	
 23	impl Package {
 24	    /// The directory of the first canonical manifest; `None` only for a package without one.
 25	    pub fn key(&self) -> Option<PackageKey> {
 26	        let manifest = self.canonical_manifests().next()?;
 27	        Some(PackageKey::new(manifest.path.parent().unwrap_or(Path::new(""))))
 28	    }
 29	
 30	    pub fn canonical_manifests(&self) -> impl Iterator<Item = &ManifestDecl> {
 31	        self.manifests.iter().filter(|m| m.role == ManifestRole::Canonical)
 32	    }
 33	
 34	    pub fn platform_manifests(&self) -> impl Iterator<Item = &ManifestDecl> {
 35	        self.manifests
 36	            .iter()
 37	            .filter(|m| matches!(m.role, ManifestRole::Platform { .. }))
 38	    }
 39	
 40	    pub fn lockfiles(&self) -> impl Iterator<Item = &ManifestDecl> {
 41	        self.manifests.iter().filter(|m| m.role == ManifestRole::Lockfile)
 42	    }
 43	
 44	    pub fn version_grammar(&self) -> Result<VersionGrammar, ModelError> {
 45	        let grammars: Vec<_> = self
 46	            .canonical_manifests()
 47	            .map(|m| m.format.ecosystem().version_grammar())
 48	            .collect();
 49	
 50	        if grammars.is_empty() {
 51	            return Err(ModelError::no_canonical_manifest(&self.id));
 52	        }
 53	
 54	        let first = grammars[0];
 55	        if grammars.iter().any(|&g| g != first) {
 56	            let unique: HashSet<_> = grammars.into_iter().collect();
 57	            return Err(ModelError::mixed_version_grammars(
 58	                &self.id,
 59	                unique.into_iter().collect(),
 60	            ));
 61	        }
 62	
 63	        Ok(first)
 64	    }
 65	
 66	    pub fn is_release_point(&self) -> bool {
 67	        self.publish_to.iter().any(|t| !matches!(t, PublishTarget::None))
 68	    }
 69	
 70	    pub fn is_dual_published(&self) -> bool {
 71	        let canonical_ecosystems: HashSet<_> = self.canonical_manifests().map(|m| m.format.ecosystem()).collect();
 72	        canonical_ecosystems.len() >= 2
 73	    }
 74	}
 75	
 76	/// Declaration of a manifest file.
 77	#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
 78	#[serde(rename_all = "camelCase")]
 79	pub struct ManifestDecl {
 80	    pub path: PathBuf,
 81	    pub role: ManifestRole,
 82	    pub format: ManifestFormat,
 83	}
 84	
 85	impl ManifestDecl {
 86	    pub fn new(path: impl AsRef<Path>, role: ManifestRole, format: ManifestFormat) -> Result<Self, ModelError> {
 87	        let rel_path = workspace_relative(path)?;
 88	
 89	        if format.is_lockfile() && role != ManifestRole::Lockfile {
 90	            return Err(ModelError::invalid_role_for_format(&role, &format));
 91	        }
 92	
 93	        if role == ManifestRole::Lockfile && !format.is_lockfile() {
 94	            return Err(ModelError::invalid_role_for_format(&role, &format));
 95	        }
 96	
 97	        if matches!(role, ManifestRole::Platform { .. }) && format == ManifestFormat::CargoToml {
 98	            return Err(ModelError::invalid_role_for_format(&role, &format));
 99	        }
100	
101	        Ok(ManifestDecl {
102	            path: rel_path,
103	            role,
104	            format,
105	        })
106	    }
107	
108	    pub fn ecosystem(&self) -> Ecosystem {
109	        self.format.ecosystem()
110	    }
111	}
112	
113	/// Role of a manifest file in a package.
114	#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
115	#[serde(rename_all = "camelCase", tag = "kind")]
116	pub enum ManifestRole {
117	    Canonical,
118	    Platform {
119	        platform: String,
120	        arch: String,
121	        abi: Option<String>,
122	    },
123	    Lockfile,
124	}
125	
126	/// Format of a manifest file.
127	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
128	#[serde(rename_all = "camelCase")]
129	#[non_exhaustive]
130	pub enum ManifestFormat {
131	    CargoToml,
132	    PackageJson,
133	    PyprojectToml,
134	    SetupCfg,
135	    GoMod,
136	    PomXml,
137	    GradleVersionCatalog,
138	    SettingsGradle,
139	    VersionSbt,
140	    DenoJson,
141	    CargoLock,
142	    PackageLockJson,
143	    PnpmLockYaml,
144	    YarnLock,
145	}
146	
147	impl ManifestFormat {
148	    pub fn ecosystem(&self) -> Ecosystem {
149	        match self {
150	            ManifestFormat::CargoToml | ManifestFormat::CargoLock => Ecosystem::Cargo,
151	            ManifestFormat::PackageJson
152	            | ManifestFormat::PackageLockJson
153	            | ManifestFormat::PnpmLockYaml
154	            | ManifestFormat::YarnLock => Ecosystem::Npm,
155	            ManifestFormat::PyprojectToml | ManifestFormat::SetupCfg => Ecosystem::Pypi,
156	            ManifestFormat::GoMod => Ecosystem::Go,
157	            ManifestFormat::PomXml
158	            | ManifestFormat::GradleVersionCatalog
159	            | ManifestFormat::SettingsGradle
160	            | ManifestFormat::VersionSbt => Ecosystem::Maven,
161	            ManifestFormat::DenoJson => Ecosystem::Deno,
162	        }
163	    }
164	
165	    pub fn is_lockfile(&self) -> bool {
166	        matches!(
167	            self,
168	            ManifestFormat::CargoLock
169	                | ManifestFormat::PackageLockJson
170	                | ManifestFormat::PnpmLockYaml
171	                | ManifestFormat::YarnLock
172	        )
173	    }
174	
175	    pub fn is_writable(&self) -> bool {
176	        !matches!(
177	            self,
178	            ManifestFormat::SetupCfg
179	                | ManifestFormat::CargoLock
180	                | ManifestFormat::PackageLockJson
181	                | ManifestFormat::PnpmLockYaml
182	                | ManifestFormat::YarnLock
183	                | ManifestFormat::SettingsGradle
184	                | ManifestFormat::VersionSbt
185	        )
186	    }
187	
188	    pub const fn file_name(&self) -> &'static str {
189	        match self {
190	            ManifestFormat::CargoToml => "Cargo.toml",
191	            ManifestFormat::PackageJson => "package.json",
192	            ManifestFormat::PyprojectToml => "pyproject.toml",
193	            ManifestFormat::SetupCfg => "setup.cfg",
194	            ManifestFormat::GoMod => "go.mod",
195	            ManifestFormat::PomXml => "pom.xml",
196	            ManifestFormat::GradleVersionCatalog => "libs.versions.toml",
197	            ManifestFormat::SettingsGradle => "settings.gradle",
198	            ManifestFormat::VersionSbt => "build.sbt",
199	            ManifestFormat::DenoJson => "deno.json",
200	            ManifestFormat::CargoLock => "Cargo.lock",
201	            ManifestFormat::PackageLockJson => "package-lock.json",
202	            ManifestFormat::PnpmLockYaml => "pnpm-lock.yaml",
203	            ManifestFormat::YarnLock => "yarn.lock",
204	        }
205	    }
206	
207	    pub fn from_path(p: &std::path::Path) -> Result<Self, ModelError> {
208	        let name = p
209	            .file_name()
210	            .and_then(|n| n.to_str())
211	            .ok_or_else(|| ModelError::UnknownManifestFormat { path: p.to_path_buf() })?;
212	        match name {
213	            "Cargo.toml" => Ok(ManifestFormat::CargoToml),
214	            "package.json" => Ok(ManifestFormat::PackageJson),
215	            "pyproject.toml" => Ok(ManifestFormat::PyprojectToml),
216	            "setup.cfg" => Ok(ManifestFormat::SetupCfg),
217	            "go.mod" => Ok(ManifestFormat::GoMod),
218	            "pom.xml" => Ok(ManifestFormat::PomXml),
219	            "deno.json" | "deno.jsonc" => Ok(ManifestFormat::DenoJson),
220	            _ => Err(ModelError::UnknownManifestFormat { path: p.to_path_buf() }),
221	        }
222	    }
223	}
