 57	pub struct Workspace<'a, R: CommandRunner, D: DependencyResolver = ManifestWalkResolver> {
 58	    pub root: PathBuf,
 59	    pub config: ResolvedConfig,
 60	    pub graph: D,
 61	    /// Deferred [`TagIndex`]: built at most once, the first time
 62	    /// [`Workspace::tags`] is called, not eagerly by [`Workspace::load`].
 63	    ///
 64	    /// `TagIndex::build` fetches the repo's full tag list with a `git tag
 65	    /// --list` spawn. Several command paths never consult tags at all (`add`'s
 66	    /// non-interactive path only needs [`Workspace::root`]; `init` only
 67	    /// needs package names/root), so building unconditionally in
 68	    /// `Workspace::load` charged every caller for work only some need. All
 69	    /// of `TagIndex::build`'s inputs are already `Workspace` fields, so a
 70	    /// `OnceCell` needs no extra state -- go through [`Workspace::tags`],
 71	    /// not this field directly.
 72	    pub tags: OnceCell<TagIndex>,
 73	    /// Deferred [`GitAccess`], built the first time [`Workspace::git_access`]
 74	    /// is called. `pub` so tests can hand-construct a `Workspace` with a
 75	    /// pre-seeded value.
 76	    pub git: OnceCell<GitAccess<'a>>,
 77	    pub runner: &'a R,
 78	    /// Path-keyed cache of manifest handles opened read-only during this
 79	    /// workspace's lifetime. Populated during graph discovery
 80	    /// (`ManifestWalkResolver::build`) and reused by read-only accessors
 81	    /// such as [`Workspace::base_versions`] so a given manifest is opened
 82	    /// (read + parsed) at most once per command run. Never consulted by the
 83	    /// manifest-open-for-write path in `apply.rs`, which always needs a
 84	    /// fresh, exclusively-owned `&mut` handle.
 85	    pub manifest_cache: RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
 86	    pub identity: IdentityIndex,
 87	}
