 89	impl<'a, R: CommandRunner> Workspace<'a, R, ManifestWalkResolver> {
 90	    pub fn load<L: ProjectLocator>(root: PathBuf, locator: &L, runner: &'a R) -> Result<Self, GraphError> {
 91	        let config = config::load(&root)?;
 92	        Self::load_with_config(root, config, locator, runner)
 93	    }
 94	
 95	    /// Builds the workspace against an already-resolved config instead of `callisto.toml`.
 96	    pub fn load_with_config<L: ProjectLocator>(
 97	        root: PathBuf,
 98	        mut config: ResolvedConfig,
 99	        locator: &L,
100	        runner: &'a R,
101	    ) -> Result<Self, GraphError> {
102	        let manifest_cache: RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>> = RefCell::new(BTreeMap::new());
103	        let graph = ManifestWalkResolver::build(&root, locator, runner, &config, &manifest_cache)?;
104	
105	        config.groups = GroupTable::resolve(&config.raw_groups, graph.identity())?;
106	
107	        {
108	            let mut by_name: BTreeMap<String, Vec<(PackageId, BTreeSet<Ecosystem>)>> = BTreeMap::new();
109	            let mut ecosystems_by_id: BTreeMap<(String, PackageId), BTreeSet<Ecosystem>> = BTreeMap::new();
110	            for ((eco, name), id) in &graph.identity().prefixed {
111	                ecosystems_by_id
112	                    .entry((name.clone(), id.clone()))
113	                    .or_default()
114	                    .insert(*eco);
115	            }
116	            for ((name, id), ecos) in ecosystems_by_id {
117	                by_name.entry(name).or_default().push((id, ecos));
118	            }
119	            config.promoted_siblings = by_name.into_iter().filter(|(_, ids)| ids.len() >= 2).collect();
120	        }
121	
122	        let identity = graph.identity().clone();
123	
124	        Ok(Workspace {
125	            root,
126	            config,
127	            graph,
128	            tags: OnceCell::new(),
129	            git: OnceCell::new(),
130	            runner,
131	            manifest_cache,
132	            identity,
133	        })
134	    }
