199	pub fn pre_json_key(id: &PackageId) -> String {
200	    id.display_name()
201	}
202	
203	/// `id`'s pinned pre-release baseline, also accepting the bare-name key older `pre.json` files used.
204	pub fn pre_initial_version<'a>(pre: &'a callisto_model::format::PreState, id: &PackageId) -> Option<&'a Version> {
205	    pre.initial_versions
206	        .get(&pre_json_key(id))
207	        .or_else(|| pre.initial_versions.get(id.name()))
208	}
