232	            ],
233	        );
234	        assert_eq!(pre_initial_version(&pre, &cargo), Some(&Version::semver(1, 0, 0)));
235	        assert_eq!(pre_initial_version(&pre, &npm), Some(&Version::semver(2, 0, 0)));
