 89	impl<'a, R: CommandRunner> Workspace<'a, R, ManifestWalkResolver> {
 90	    pub fn load<L: ProjectLocator>(root: PathBuf, locator: &L, runner: &'a R) -> Result<Self, GraphError> {
 91	        let config = config::load(&root)?;
 92	        Self::load_with_config(root, config, locator, runner)
 93	    }
 94	
 95	    /// Builds the workspace against an already-resolved config instead of `callisto.toml`.
 96	    pub fn load_with_config<L: ProjectLocator>(
 97	        root: PathBuf,
 98	        mut config: ResolvedConfig,
 99	        locator: &L,
100	        runner: &'a R,
101	    ) -> Result<Self, GraphError> {
102	        let manifest_cache: RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>> = RefCell::new(BTreeMap::new());
103	        let graph = ManifestWalkResolver::build(&root, locator, runner, &config, &manifest_cache)?;
104	
105	        config.groups = GroupTable::resolve(&config.raw_groups, graph.identity())?;
106	
107	        {
108	            let mut by_name: BTreeMap<String, Vec<(PackageId, BTreeSet<Ecosystem>)>> = BTreeMap::new();
109	            let mut ecosystems_by_id: BTreeMap<(String, PackageId), BTreeSet<Ecosystem>> = BTreeMap::new();
110	            for ((eco, name), id) in &graph.identity().prefixed {
111	                ecosystems_by_id
112	                    .entry((name.clone(), id.clone()))
113	                    .or_default()
114	                    .insert(*eco);
115	            }
116	            for ((name, id), ecos) in ecosystems_by_id {
117	                by_name.entry(name).or_default().push((id, ecos));
118	            }
119	            config.promoted_siblings = by_name.into_iter().filter(|(_, ids)| ids.len() >= 2).collect();
120	        }
121	
122	        let identity = graph.identity().clone();
123	
124	        Ok(Workspace {
125	            root,
126	            config,
127	            graph,
128	            tags: OnceCell::new(),
129	            git: OnceCell::new(),
130	            runner,
131	            manifest_cache,
132	            identity,
133	        })
134	    }
135	}
136	
137	impl<'a, R: CommandRunner, D: DependencyResolver> Workspace<'a, R, D> {
138	    /// Returns the workspace's [`TagIndex`], building it on first access and
139	    /// reusing the cached result afterwards. See the doc comment on the
140	    /// `tags` field for why this is deferred rather than built eagerly by
141	    /// [`Workspace::load`].
142	    pub fn tags(&self) -> Result<&TagIndex, GraphError> {
143	        if let Some(existing) = self.tags.get() {
144	            return Ok(existing);
145	        }
146	        let built = TagIndex::build(self.git_access(), &self.graph, &self.config)?;
147	        // `OnceCell::set` only fails if another write already raced it in;
148	        // `Workspace` is only ever accessed through `&self` here (never
149	        // shared across threads -- `R`/`D` carry no such bound), so the
150	        // `get()` check above already ruled that out. Fall back to `get()`
151	        // either way rather than trusting the `set` call's own return value,
152	        // so this stays correct even if that assumption ever changes.
153	        self.tags.set(built).ok();
154	        Ok(self
155	            .tags
156	            .get()
157	            .expect("tags was just set above, or already set by a prior call"))
158	    }
159	
160	    /// Returns the workspace's shared [`GitAccess`], rooted at the workspace
161	    /// root and running `git` through the workspace's runner.
162	    pub fn git_access(&self) -> &GitAccess<'a> {
163	        self.git.get_or_init(|| GitAccess::new(&self.root, self.runner))
164	    }
165	
166	    pub fn base_versions(&self) -> Result<BTreeMap<PackageId, Version>, GraphError> {
167	        let ctx = callisto_manifests::OpenContext::for_workspace_root(&self.root);
168	
169	        let mut versions = BTreeMap::new();
170	        for pkg in self.graph.packages() {
171	            let mut found_version = None;
172	            for decl in &pkg.manifests {
173	                if decl.role == callisto_model::ManifestRole::Canonical {
174	                    let handle = manifest_cache::open_cached(&self.manifest_cache, decl, &ctx)?;
175	                    let v = handle.current_version()?;
176	                    found_version = Some(v);
177	                    break;
178	                }
179	            }
180	            if let Some(version) = found_version {
181	                versions.insert(pkg.id.clone(), version);
182	            } else {
183	                return Err(GraphError::Manifest(callisto_model::ManifestError::MissingField {
184	                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
185	                    field: "version",
186	                }));
187	            }
188	        }
189	        Ok(versions)
190	    }
191	
192	    pub fn initial_versions(&self) -> Result<Vec<(String, Version)>, GraphError> {
193	        let base = self.base_versions()?;
194	        Ok(base.into_iter().map(|(id, v)| (pre_json_key(&id), v)).collect())
195	    }
196	}
