330	        return Err(GraphError::ReleaseCommitVerificationFailed {
331	            commit: release_commit.clone(),
332	            reason: CommitVerificationFailure::HeadMismatch,
333	        });
334	    }
335	
336	    let parent_ref = format!("{}^", release_commit.as_str());
337	    let parent_args = ["rev-parse", parent_ref.as_str()];
338	    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
339	    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;
340	
341	    let diff_tree_args = [
342	        "diff-tree",
343	        "--no-commit-id",
344	        "--name-status",
345	        "-r",
346	        "--no-renames",
347	        parent.as_str(),
348	        release_commit.as_str(),
349	    ];
350	    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
351	    let changed = parse_name_status(&changed, &diff_tree_args)?;
352	
353	    // The decision must be freshly authored as part of *this* commit, not a
354	    // stale leftover an earlier release already committed and this one never
355	    // touched -- otherwise a commit that changes nothing real could still
356	    // carry forward a prior, unrelated decision's authority.
357	    let decision_path_str = decision_path.to_string_lossy().replace('\\', "/");
358	    let decision_freshly_written = changed
359	        .iter()
360	        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
361	    if !decision_freshly_written {
362	        return Err(GraphError::ReleaseCommitVerificationFailed {
363	            commit: release_commit.clone(),
364	            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
365	        });
366	    }
367	
368	    // A cheap, independent sanity check that this commit is a real version
369	    // application and not just a hand-crafted decision file: some real
370	    // changeset was actually consumed. The decision's own entries, not this
371	    // changeset's content, remain the sole authority verified below.
372	    let changeset_dir = workspace.config.changesets_dir.to_string_lossy().replace('\\', "/");
373	    let changeset_prefix = format!("{}/", changeset_dir.trim_end_matches('/'));
374	    let consumed_a_changeset = changed
375	        .iter()
376	        .any(|(status, path)| status == "D" && path.starts_with(&changeset_prefix) && path.ends_with(".md"));
377	    if !consumed_a_changeset {
378	        return Err(GraphError::ReleaseCommitVerificationFailed {
379	            commit: release_commit.clone(),
380	            reason: CommitVerificationFailure::NoChangesetConsumed,
381	        });
382	    }
383	
384	    let decision_source = git_file(
385	        workspace.runner,
386	        &workspace.root,
387	        release_commit.as_str(),
388	        &decision_path_str,
389	    )?;
390	    let decision: ReleaseDecisionV1 =
391	        serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
392	            path: decision_path.to_path_buf(),
393	            message: error.to_string(),
394	        })?;
395	    let claimed = decision
396	        .entries
397	        .iter()
398	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
399	        .collect::<std::collections::BTreeMap<_, _>>();
400	
401	    let changed_paths = changed
402	        .iter()
403	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
404	        .collect::<std::collections::BTreeSet<_>>();
405	
406	    // Every canonical manifest path this workspace currently declares, in
407	    // the exact order `workspace.graph.packages()` and
408	    // `Package::canonical_manifests()` yield -- both are backed by ordered
409	    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
410	    // the second traversal below visits the same (package, manifest) pairs
411	    // in the same order. That lets it zip the batched `before`/`after`
412	    // results back on by position instead of re-keying by path, which would
413	    // misbehave if two packages ever declared an identical manifest path.
414	    let manifest_queries: Vec<(String, Ecosystem)> = workspace
415	        .graph
416	        .packages()
417	        .flat_map(Package::canonical_manifests)
418	        .map(|manifest| (manifest.path.to_string_lossy().into_owned(), manifest.ecosystem()))
419	        .collect();
420	    let query_paths: Vec<&str> = manifest_queries.iter().map(|(path, _)| path.as_str()).collect();
421	
422	    // Exactly two `git cat-file --batch` subprocess invocations total (one
423	    // per commit), regardless of how many canonical manifests the
424	    // workspace has -- replaces what was previously 2*N separate `git
425	    // show` spawns (one `manifest_version_at` call per manifest per
426	    // commit).
427	    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, &parent, &query_paths)?;
428	    let after_blobs =
429	        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
430	    let before_versions = resolve_batch_versions(before_blobs, &manifest_queries)?;
431	    let after_versions = resolve_batch_versions(after_blobs, &manifest_queries)?;
432	
433	    let mut observed = std::collections::BTreeSet::new();
434	    let mut manifest_index = 0usize;
435	    for package in workspace.graph.packages() {
436	        let package_ids = release_package_ids(&workspace.identity, package)?;
437	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
438	        if package_is_claimed {
439	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
440	                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
441	            })?;
442	            if !changed_paths.contains(changelog.to_string_lossy().as_ref()) {
443	                return Err(GraphError::ReleaseCommitVerificationFailed {
444	                    commit: release_commit.clone(),
445	                    reason: CommitVerificationFailure::ChangelogNotTouched,
446	                });
447	            }
448	        }
449	        for (manifest, id) in package.canonical_manifests().zip(package_ids) {
450	            let path = manifest.path.to_string_lossy();
451	            let before = &before_versions[manifest_index];
452	            let after = &after_versions[manifest_index];
453	            manifest_index += 1;
454	            let changed_version = before != after;
455	            match claimed.get(&id) {
456	                Some(target_version) => {
457	                    if !changed_paths.contains(path.as_ref()) {
458	                        return Err(GraphError::ReleaseCommitVerificationFailed {
459	                            commit: release_commit.clone(),
460	                            reason: CommitVerificationFailure::ManifestNotInDiff,
461	                        });
462	                    }
463	                    if !changed_version || after != target_version {
464	                        return Err(GraphError::ReleaseCommitVerificationFailed {
465	                            commit: release_commit.clone(),
466	                            reason: CommitVerificationFailure::ManifestVersionMismatch,
467	                        });
468	                    }
469	                    observed.insert(id);
470	                }
471	                None => {
472	                    if changed_version {
473	                        // A changed version the committed decision never
474	                        // claimed is not this commit's authority -- fail
475	                        // closed rather than trust a partial match.
476	                        return Err(GraphError::ReleaseCommitVerificationFailed {
477	                            commit: release_commit.clone(),
478	                            reason: CommitVerificationFailure::UnclaimedVersionChange,
479	                        });
480	                    }
481	                }
482	            }
483	        }
484	    }
485	    if observed.len() != claimed.len() {
486	        return Err(GraphError::ReleaseCommitVerificationFailed {
487	            commit: release_commit.clone(),
488	            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
489	        });
490	    }
491	
492	    Ok(decision)
493	}
