351	/// True when a canonical manifest differs between index and HEAD: `git add`ed by a prior `apply` but never committed.
352	fn any_canonical_manifest_staged_uncommitted<R: CommandRunner, D: DependencyResolver>(
353	    ws: &Workspace<'_, R, D>,
354	) -> Result<bool, GraphError> {
355	    for pkg in ws.graph.packages() {
356	        for decl in pkg.canonical_manifests() {
357	            let path_str = decl.path.to_string_lossy();
358	            let output = ws
359	                .runner
360	                .run(
361	                    "git",
362	                    &["diff", "--cached", "--quiet", "--", path_str.as_ref()],
363	                    &ws.root,
364	                )
365	                .map_err(GraphError::Command)?;
366	            // `git diff --quiet` exits 1 on a difference, 0 on none; any other exit code is treated as no signal.
367	            if output.exit_code == Some(1) {
368	                return Ok(true);
369	            }
370	        }
371	    }
372	    Ok(false)
373	}
