 630	impl ReleaseDecisionV1 {
 631	    pub const SCHEMA_VERSION: u8 = 2;
 632	    /// Version 1 differs only in lacking `unreleasedVersion`, so a committed v1 decision still reads.
 633	    pub const READABLE_SCHEMA_VERSIONS: [u8; 2] = [1, 2];
 634	
 635	    /// Creates a canonical decision or rejects an ambiguous release roster.
 636	    #[allow(clippy::result_large_err)]
 637	    pub fn new(mut entries: Vec<ReleaseDecisionEntry>) -> Result<Self, ReleaseDecisionError> {
 638	        if entries.is_empty() {
 639	            return Err(ReleaseDecisionError::EmptyRoster);
 640	        }
 641	        for entry in &mut entries {
 642	            entry.reasons.sort();
 643	            entry.reasons.dedup();
 644	            if entry.reasons.is_empty() {
 645	                return Err(ReleaseDecisionError::MissingReason {
 646	                    package: entry.package.clone(),
 647	                });
 648	            }
 649	        }
 650	        entries.sort_by(|left, right| left.package.cmp(&right.package));
 651	        if entries.windows(2).any(|pair| pair[0].package == pair[1].package) {
 652	            return Err(ReleaseDecisionError::DuplicatePackage);
 653	        }
 654	
 655	        // A fixed or linked group always converges every member to one
 656	        // shared target version -- `solve_cascade` guarantees this when a
 657	        // decision is derived from a version plan. Entries tag their own
 658	        // group membership via `FixedGroup`/`LinkedGroup` reasons, so this
 659	        // invariant is checkable from the decision's own content alone, with
 660	        // no `GroupTable`/workspace-config access needed. Rejecting a
 661	        // violation here means it also applies to a decision deserialized
 662	        // from a committed release-decision file (`Deserialize` calls
 663	        // `new()`), not just one freshly derived from a plan.
 664	        let mut group_targets: BTreeMap<&str, &Version> = BTreeMap::new();
 665	        for entry in &entries {
 666	            for reason in &entry.reasons {
 667	                let group_id = match reason {
 668	                    ReleaseInclusionReason::FixedGroup { group_id }
 669	                    | ReleaseInclusionReason::LinkedGroup { group_id } => group_id.as_str(),
 670	                    _ => continue,
 671	                };
 672	                match group_targets.get(group_id) {
 673	                    Some(existing) if **existing != entry.target_version => {
 674	                        return Err(ReleaseDecisionError::DivergentGroupTarget {
 675	                            group_id: group_id.to_string(),
 676	                            left: (*existing).clone(),
 677	                            right: entry.target_version.clone(),
 678	                        });
 679	                    }
 680	                    _ => {
 681	                        group_targets.insert(group_id, &entry.target_version);
 682	                    }
 683	                }
 684	            }
 685	        }
 686	
 687	        let digest = decision_digest(&entries);
 688	        Ok(Self {
 689	            schema_version: Self::SCHEMA_VERSION,
 690	            entries,
 691	            digest,
 692	        })
 693	    }
 694	}
 695	
 696	fn decision_digest(entries: &[ReleaseDecisionEntry]) -> DecisionDigest {
 697	    let mut transcript = CanonicalTranscript::decision_v1();
 698	    for entry in entries {
 699	        transcript.push_str("package", &entry.package.to_string());
 700	        transcript.push_str("target-version", entry.target_version.render());
 701	        for reason in &entry.reasons {
 702	            transcript.push_str(
 703	                "reason",
 704	                &serde_json::to_string(reason).expect("closed reason serializes"),
 705	            );
 706	        }
 707	    }
 708	    DecisionDigest::from_transcript(&transcript)
 709	}
