 27	#[schemars(with = "String")]
 28	pub struct Version {
 29	    pub(crate) grammar: VersionGrammar,
 30	    pub(crate) raw: String,
 31	    #[schemars(skip)]
 32	    pub(crate) parsed: ParsedVersion,
 33	}
 34	
 35	impl Version {
 36	    pub fn parse(raw: &str, grammar: VersionGrammar) -> Result<Self, VersionParseError> {
 37	        match grammar {
 38	            VersionGrammar::SemVer => {
 39	                let parsed = semver::Version::parse(raw).map_err(|e| VersionParseError {
 40	                    raw: raw.to_string(),
 41	                    grammar,
 42	                    message: e.to_string(),
 43	                })?;
 44	                Ok(Version {
 45	                    grammar,
 46	                    raw: raw.to_string(),
 47	                    parsed: ParsedVersion::SemVer(parsed),
 48	                })
 49	            }
 50	            VersionGrammar::Pep440 => {
 51	                let parsed = raw.parse::<pep440_rs::Version>().map_err(|e| VersionParseError {
 52	                    raw: raw.to_string(),
 53	                    grammar,
 54	                    message: e.to_string(),
 55	                })?;
 56	                // PEP 440 defines multiple equivalent spellings for the same
 57	                // version (e.g. `1.0.0-alpha1`, `1.0.0_alpha1`, `1.0.0a1`).
 58	                // Normalize `raw` to pep440_rs's canonical rendering so that
 59	                // logically-equal inputs produce identical `raw` values, and
 60	                // therefore compare `==` and hash equal (derived PartialEq/Eq/
 61	                // Hash include `raw`). SemVer has no analogous normalization
 62	                // requirement (each version already has one canonical form),
 63	                // so the caller's literal input is preserved for that grammar.
 64	                let canonical = parsed.to_string();
 65	                Ok(Version {
 66	                    grammar,
 67	                    raw: canonical,
 68	                    parsed: ParsedVersion::Pep440(parsed),
 69	                })
 70	            }
 71	            VersionGrammar::Maven => Err(VersionParseError {
 72	                raw: raw.to_string(),
 73	                grammar,
 74	                message: format!("{grammar:?} has no versioning implementation yet"),
 75	            }),
 76	        }
 77	    }
 78	
 79	    pub fn semver(major: u64, minor: u64, patch: u64) -> Self {
 80	        let parsed = semver::Version::new(major, minor, patch);
 81	        Version {
 82	            grammar: VersionGrammar::SemVer,
 83	            raw: parsed.to_string(),
 84	            parsed: ParsedVersion::SemVer(parsed),
 85	        }
 86	    }
 87	
 88	    pub fn grammar(&self) -> VersionGrammar {
 89	        self.grammar
 90	    }
 91	
 92	    pub fn render(&self) -> &str {
 93	        &self.raw
 94	    }
 95	
 96	    pub fn raw(&self) -> &str {
 97	        &self.raw
 98	    }
 99	
100	    pub fn major(&self) -> Option<u64> {
101	        match &self.parsed {
102	            ParsedVersion::SemVer(v) => Some(v.major),
103	            ParsedVersion::Pep440(v) => v.release().first().copied(),
104	        }
105	    }
106	
107	    pub fn minor(&self) -> Option<u64> {
108	        match &self.parsed {
109	            ParsedVersion::SemVer(v) => Some(v.minor),
110	            ParsedVersion::Pep440(v) => v.release().get(1).copied(),
111	        }
112	    }
113	
114	    pub fn patch(&self) -> Option<u64> {
115	        match &self.parsed {
116	            ParsedVersion::SemVer(v) => Some(v.patch),
117	            ParsedVersion::Pep440(v) => v.release().get(2).copied(),
118	        }
119	    }
120	
121	    pub fn is_prerelease(&self) -> bool {
122	        match &self.parsed {
123	            ParsedVersion::SemVer(v) => !v.pre.is_empty(),
124	            ParsedVersion::Pep440(v) => !v.is_post() && (v.is_pre() || v.is_dev()),
125	        }
126	    }
127	
128	    pub fn compare(&self, other: &Version) -> Result<std::cmp::Ordering, GrammarMismatch> {
129	        if self.grammar != other.grammar {
130	            return Err(GrammarMismatch {
131	                left: self.grammar,
132	                right: other.grammar,
133	            });
134	        }
135	        match (&self.parsed, &other.parsed) {
136	            (ParsedVersion::SemVer(a), ParsedVersion::SemVer(b)) => Ok(a.cmp(b)),
137	            (ParsedVersion::Pep440(a), ParsedVersion::Pep440(b)) => Ok(a.cmp(b)),
138	            _ => unreachable!(),
139	        }
140	    }
141	
142	    pub fn partial_compare(&self, other: &Version) -> Option<std::cmp::Ordering> {
143	        self.compare(other).ok()
144	    }
145	}
