     2	//!
     3	//! A bare four-state observation let "the object exists" stand in for "the
     4	//! object is exactly what this intent authorized", so a receipt's observation
     5	//! map proved nothing. Every non-absent state here carries the closed,
     6	//! credential-free proof the provider actually produced, and the only tokens
     7	//! that authorize a state transition are minted from one of these states.
     8	
     9	use schemars::JsonSchema;
    10	use serde::{Deserialize, Serialize};
    11	
    12	use crate::release::{ReleaseOperationId, ReleaseOperationRole};
    13	use crate::tag::TagName;
    14	use crate::{ArtifactDigest, CommitSha, Version};
    15	
    16	/// What a provider proved about one operation's remote identity.
    17	///
    18	/// Closed and per-role: an adapter may only report what its provider can
    19	/// demonstrate today. Fields that a provider cannot yet report are `None`
    20	/// rather than invented.
    21	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
    22	#[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
    23	pub enum ProviderEvidenceV1 {
    24	    /// The registry served this exact version.
    25	    RegistryVersion {
    26	        version: Version,
    27	        /// `None` until the configured client reports a package checksum.
    28	        #[serde(default, skip_serializing_if = "Option::is_none")]
    29	        checksum: Option<ArtifactDigest>,
    30	        /// `None` until the configured client reports yank status.
    31	        #[serde(default, skip_serializing_if = "Option::is_none")]
    32	        yanked: Option<bool>,
    33	    },
    34	    /// An annotated tag on the release remote, resolved to its commit.
    35	    GitTag {
    36	        peeled_commit: CommitSha,
    37	    },
    38	    ForgeRelease {
    39	        tag_name: TagName,
    40	        draft: bool,
    41	    },
    42	    ArtifactUpload {
    43	        byte_length: u64,
    44	        sha256: ArtifactDigest,
    45	    },
    46	}
    47	
    48	/// Why one piece of evidence cannot stand for one operation's role.
    49	enum EvidenceRejection {
    50	    Role,
    51	    DraftRelease,
    52	}
    53	
    54	impl ProviderEvidenceV1 {
    55	    /// Both forge roles are proved by the same GitHub Release object; only the
    56	    /// `draft` flag separates "the draft exists" from "the release is published".
    57	    fn check_role(&self, role: &ReleaseOperationRole) -> Result<(), EvidenceRejection> {
    58	        match (self, role) {
    59	            (Self::ForgeRelease { draft, .. }, ReleaseOperationRole::ForgePublish) => {
    60	                (!draft).then_some(()).ok_or(EvidenceRejection::DraftRelease)
    61	            }
    62	            (Self::RegistryVersion { .. }, ReleaseOperationRole::RegistryPublish { .. })
    63	            | (Self::RegistryVersion { .. }, ReleaseOperationRole::PlatformPublish { .. })
    64	            | (Self::GitTag { .. }, ReleaseOperationRole::Tag)
    65	            | (Self::ForgeRelease { .. }, ReleaseOperationRole::ForgeRelease)
    66	            | (Self::ArtifactUpload { .. }, ReleaseOperationRole::ArtifactUpload { .. }) => Ok(()),
    67	            _ => Err(EvidenceRejection::Role),
    68	        }
    69	    }
    70	}
    71	
    72	/// Why an existing remote object is not the one this intent authorized.
    73	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
    74	#[serde(rename_all = "camelCase")]
    75	#[non_exhaustive]
    76	pub enum ProviderConflictReason {
    77	    /// A local tag ref names another commit, or is lightweight.
    78	    LocalTagDiffers,
    79	    /// The remote tag resolves to a different commit.
    80	    RemoteTagTargetDiffers,
    81	    /// The remote tag is lightweight, so it carries no release annotation.
    82	    UnannotatedTag,
    83	    /// The forge release exists but names another tag.
    84	    ForgeReleaseDiffers,
    85	    /// A release for this tag exists, but its `prerelease` flag disagrees with
    86	    /// the released version's semver pre-release part.
    87	    ForgeReleasePrereleaseDiffers,
    88	    /// The release asset exists with different bytes or length.
    89	    ArtifactAssetDiffers,
    90	    /// Several assets share the slot's asset name.
    91	    DuplicateArtifactAsset,
    92	    /// The registry serves this version, but it is yanked.
    93	    RegistryVersionYanked,
    94	}
    95	
    96	/// Why remote identity could not be established at all.
    97	///
    98	/// Indeterminate is never a conflict: an authentication, rate-limit, or
    99	/// transport failure must not be reported as a disagreeing remote object.
   100	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
   101	#[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
   102	#[non_exhaustive]
   103	pub enum ProviderIndeterminateCause {
   104	    /// No client for this provider can prove a version present or absent.
   105	    UnsupportedProvider,
   106	    /// The provider answered with a status that proves neither presence nor absence.
   107	    ProviderStatus {
   108	        status: u16,
   109	    },
   110	    CommandFailed,
   111	    MalformedResponse,
   112	    Timeout,
   113	    /// The version exists but its identity was not observed.
   114	    RegistryVersionUnverified,
   115	    /// Asset identity needs the verified artifact manifest, which was absent.
   116	    ArtifactManifestUnavailable,
   117	}
   118	
   119	/// The result of observing the exact remote identity of a release operation.
   120	///
   121	/// No arbitrary provider response is persisted: every variant carries only
   122	/// closed, credential-free, action-relevant data.
   123	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
   124	#[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
   125	pub enum ProviderObservationV1 {
   159	/// evidence the provider produced.
   160	#[derive(Debug)]
   161	pub struct ExactEvidence(ProviderEvidenceV1);
   162	
   163	impl ExactEvidence {
   164	    pub fn evidence(&self) -> &ProviderEvidenceV1 {
   165	        &self.0
   166	    }
   167	
   168	    pub fn into_evidence(self) -> ProviderEvidenceV1 {
   169	        self.0
   170	    }
   171	}
   172	
   173	/// One provider observation bound to an exact operation in an immutable intent.
   174	///
   175	/// The single constructor rejects evidence whose shape does not belong to the
   176	/// operation's role, so a forge-release proof can never satisfy a registry
   177	/// publish. Deserialization goes through the same constructor.
   178	#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
   179	#[serde(rename_all = "camelCase", deny_unknown_fields)]
   180	pub struct ReleaseOperationObservationV1 {
   181	    operation: ReleaseOperationId,
   182	    observation: ProviderObservationV1,
   183	}
   184	
   185	#[derive(Deserialize)]
   186	#[serde(rename_all = "camelCase", deny_unknown_fields)]
   187	struct ReleaseOperationObservationV1Wire {
   188	    operation: ReleaseOperationId,
   189	    observation: ProviderObservationV1,
   190	}
   191	
   192	impl<'de> Deserialize<'de> for ReleaseOperationObservationV1 {
   193	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
   194	    where
   195	        D: serde::Deserializer<'de>,
   196	    {
   197	        let wire = ReleaseOperationObservationV1Wire::deserialize(deserializer)?;
   198	        Self::new(wire.operation, wire.observation).map_err(serde::de::Error::custom)
   199	    }
   200	}
   201	
   202	impl ReleaseOperationObservationV1 {
   203	    pub fn new(
   204	        operation: ReleaseOperationId,
   205	        observation: ProviderObservationV1,
   206	    ) -> Result<Self, ProviderObservationError> {
   207	        if let ProviderObservationV1::Exact { evidence } = &observation {
   208	            match evidence.check_role(&operation.role) {
   209	                Ok(()) => {}
   210	                Err(EvidenceRejection::Role) => {
   211	                    return Err(ProviderObservationError::EvidenceRoleMismatch {
   212	                        id: Box::new(operation),
   213	                    })
   214	                }
   215	                Err(EvidenceRejection::DraftRelease) => {
   216	                    return Err(ProviderObservationError::DraftReleaseCannotProvePublication {
   217	                        id: Box::new(operation),
   218	                    })
   219	                }
   220	            }
   221	        }
   222	        Ok(Self { operation, observation })
   223	    }
   224	
   225	    pub fn operation(&self) -> &ReleaseOperationId {
   226	        &self.operation
   227	    }
   228	
   229	    pub fn observation(&self) -> &ProviderObservationV1 {
   230	        &self.observation
   231	    }
   232	
   233	    pub fn into_parts(self) -> (ReleaseOperationId, ProviderObservationV1) {
   234	        (self.operation, self.observation)
   235	    }
   236	}
   237	
   238	#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
   239	#[non_exhaustive]
   240	pub enum ProviderObservationError {
   241	    #[error("provider evidence does not belong to the role of release operation `{id:?}`")]
   242	    EvidenceRoleMismatch { id: Box<ReleaseOperationId> },
   243	    #[error("a draft forge release cannot prove publication of release operation `{id:?}`")]
   244	    DraftReleaseCannotProvePublication { id: Box<ReleaseOperationId> },
   245	}
"}}

