198	/// The `pre.json` `initialVersions` key for `id`: its display id, so `cargo/foo` and `npm/foo` never share an entry.
199	pub fn pre_json_key(id: &PackageId) -> String {
200	    id.display_name()
201	}
202	
203	/// `id`'s pinned pre-release baseline.
204	pub fn pre_initial_version<'a>(pre: &'a callisto_model::format::PreState, id: &PackageId) -> Option<&'a Version> {
205	    pre.initial_versions.get(&pre_json_key(id))
206	}
207	
208	/// The one package among `candidates` whose canonical manifest existed at `rev`, if exactly one did: the owner
209	/// of anything recorded under their shared bare name at that point.
210	pub(crate) fn sole_owner_at<'p>(
211	    git: &GitAccess<'_>,
212	    rev: &str,
213	    candidates: &[&'p callisto_model::Package],
214	) -> Result<Option<&'p callisto_model::Package>, GraphError> {
215	    let mut owner = None;
216	    for pkg in candidates {
217	        let Some(manifest) = pkg.canonical_manifests().next() else {
218	            continue;
219	        };
220	        if git.path_exists_at(rev, &manifest.path).map_err(GraphError::Vcs)? {
221	            if owner.is_some() {
222	                return Ok(None);
223	            }
224	            owner = Some(*pkg);
225	        }
226	    }
227	    Ok(owner)
228	}
229	
230	/// Re-keys each `initialVersions` entry recorded under a bare name that has since been promoted to the one
231	/// same-named package that existed when `pre.json` was added.
232	pub(crate) fn assign_promoted_pre_keys<D: DependencyResolver>(
233	    git: &GitAccess<'_>,
234	    graph: &D,
235	    pre_json: &std::path::Path,
236	    mut state: callisto_model::format::PreState,
237	) -> Result<callisto_model::format::PreState, GraphError> {
238	    let keys: Vec<String> = state.initial_versions.keys().cloned().collect();
239	    for key in keys {
240	        if graph.packages().any(|p| pre_json_key(&p.id) == key) {
241	            continue;
242	        }
243	        let same: Vec<&callisto_model::Package> = graph
244	            .packages()
245	            .filter(|p| p.id.ecosystem().is_some() && p.id.name() == key)
246	            .collect();
247	        if same.is_empty() {
248	            continue;
249	        }
250	        let owner = match git.commit_adding(pre_json).map_err(GraphError::Vcs)? {
251	            Some(added) => sole_owner_at(git, &added, &same)?,
252	            None => None,
253	        };
254	        let Some(owner) = owner else {
255	            return Err(GraphError::AmbiguousPreJsonKey {
256	                key,
257	                candidates: same.iter().map(|p| p.id.clone()).collect(),
258	            });
259	        };
260	        if let Some(version) = state.initial_versions.shift_remove(&key) {
261	            state.initial_versions.entry(pre_json_key(&owner.id)).or_insert(version);
262	        }
263	    }
264	    Ok(state)
265	}
