  1	//! The local `callisto release` route: select every unreleased package and
  2	//! derive its intent, for both the preview and the run.
  3	
  4	use std::path::Path;
  5	
  6	use callisto_model::{CommandRunner, ExecutionTrustProfileV1, ReleaseIntentV1, ReleasePackageId, SourceIdentity};
  7	
  8	use crate::{DependencyResolver, GraphError, ProjectLocator, Workspace};
  9	
 10	use super::binding::optional_git_remote;
 11	use super::capability::{canonical_root, observe_source, ReleaseCheckout};
 12	use super::derive::{derive_release_intent, ArtifactBuildPolicy, GitRemoteRequirement};
 13	use super::StaleReason;
 14	
 15	/// How a local release observes its source commit.
 16	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
 17	pub enum LocalReleaseSource {
 18	    /// `--dry-run`: HEAD's commit, whatever the worktree state.
 19	    Preview,
 20	    /// A real run: HEAD's commit from a clean worktree, on any branch.
 21	    Trusted,
 22	}
 23	
 24	/// Why a workspace must release through the CI plan/build/execute route.
 25	#[derive(Clone, Debug, PartialEq, Eq)]
 26	pub enum CiReleaseRoute {
 27	    /// The workspace declares `[[release.artifact]]` slots.
 28	    ArtifactSlots,
 29	    /// A package ships napi or maturin platform builds.
 30	    PlatformPackage { package: String },
 31	}
 32	
 33	impl std::fmt::Display for CiReleaseRoute {
 34	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 35	        match self {
 36	            CiReleaseRoute::ArtifactSlots => formatter.write_str("the workspace declares [[release.artifact]] slots"),
 37	            CiReleaseRoute::PlatformPackage { package } => {
 38	                write!(formatter, "package `{package}` ships napi/maturin platform builds")
 39	            }
 40	        }
 41	    }
 42	}
 43	
 44	/// The reason this workspace cannot release locally, if any.
 45	pub fn ci_release_route<R: CommandRunner, D: DependencyResolver>(
 46	    workspace: &Workspace<'_, R, D>,
 47	) -> Result<Option<CiReleaseRoute>, GraphError> {
 48	    if workspace
 49	        .config
 50	        .product_release
 51	        .as_ref()
 52	        .is_some_and(|release| !release.artifacts.is_empty())
 53	    {
 54	        return Ok(Some(CiReleaseRoute::ArtifactSlots));
 55	    }
 56	    if let Some(package) = workspace.graph.packages().find(|package| {
 57	        super::derive::is_platform_package(package) || workspace.identity.platforms_of(&package.id).next().is_some()
 58	    }) {
 59	        return Ok(Some(CiReleaseRoute::PlatformPackage {
 60	            package: package.id.display_name(),
 61	        }));
 62	    }
 63	    let matrix = crate::commands::matrix(workspace, &crate::commands::MatrixOptions::default())?;
 64	    Ok(matrix
 65	        .platform_targets
 66	        .keys()
 67	        .next()
 68	        .map(|package| CiReleaseRoute::PlatformPackage {
 69	            package: package.clone(),
 70	        }))
 71	}
 72	
 73	/// A derived local release.
 74	#[derive(Clone, Debug, PartialEq, Eq)]
 75	pub struct LocalReleasePlan {
 76	    pub intent: ReleaseIntentV1,
 77	    /// A preview only: `origin` has no push URL, so tags carry no remote and a run would refuse.
 78	    pub tags_unbound: bool,
 79	    /// Advisory findings from derivation (e.g. an artifact owner selected without its product).
 80	    pub diagnostics: Vec<callisto_model::Diagnostic>,
 81	}
 82	
 83	/// Derives the intent for every unreleased package (or exactly `selections`).
 84	///
 85	/// This is the one plan derivation behind both `callisto release --dry-run`
 86	/// and `callisto release`; `None` means nothing is unreleased.
 87	pub fn plan_local_release<L: ProjectLocator, R: CommandRunner>(
 88	    root: &Path,
 89	    locator: &L,
 90	    runner: &R,
 91	    selections: &[ReleasePackageId],
 92	    mode: LocalReleaseSource,
 93	) -> Result<Option<LocalReleasePlan>, GraphError> {
 94	    let root = canonical_root(root)?;
 95	    let workspace = Workspace::load(root, locator, runner)?;
 96	    plan_workspace_release(&workspace, selections, mode)
