 24	/// Why a workspace must release through the CI plan/build/execute route.
 25	#[derive(Clone, Debug, PartialEq, Eq)]
 26	pub enum CiReleaseRoute {
 27	    /// The workspace declares `[[release.artifact]]` slots.
 28	    ArtifactSlots,
 29	    /// A package ships napi or maturin platform builds.
 30	    PlatformPackage { package: String },
 31	}
 32	
 33	impl std::fmt::Display for CiReleaseRoute {
 34	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 35	        match self {
 36	            CiReleaseRoute::ArtifactSlots => formatter.write_str("the workspace declares [[release.artifact]] slots"),
 37	            CiReleaseRoute::PlatformPackage { package } => {
 38	                write!(formatter, "package `{package}` ships napi/maturin platform builds")
 39	            }
 40	        }
 41	    }
 42	}
