 44	/// The reason this workspace cannot release locally, if any.
 45	pub fn ci_release_route<R: CommandRunner, D: DependencyResolver>(
 46	    workspace: &Workspace<'_, R, D>,
 47	) -> Result<Option<CiReleaseRoute>, GraphError> {
 48	    if workspace
 49	        .config
 50	        .product_release
 51	        .as_ref()
 52	        .is_some_and(|release| !release.artifacts.is_empty())
 53	    {
 54	        return Ok(Some(CiReleaseRoute::ArtifactSlots));
 55	    }
 56	    if let Some(package) = workspace.graph.packages().find(|package| {
 57	        super::derive::is_platform_package(package) || workspace.identity.platforms_of(&package.id).next().is_some()
 58	    }) {
 59	        return Ok(Some(CiReleaseRoute::PlatformPackage {
 60	            package: package.id.display_name(),
 61	        }));
 62	    }
 63	    let matrix = crate::commands::matrix(workspace, &crate::commands::MatrixOptions::default())?;
 64	    Ok(matrix
 65	        .platform_targets
 66	        .keys()
 67	        .next()
 68	        .map(|package| CiReleaseRoute::PlatformPackage {
 69	            package: package.clone(),
 70	        }))
 71	}
