176	/// failure is transient: `ls-remote` is a read, so retrying it cannot have an
177	/// effect.
178	fn observed_remote_tag(
179	    context: &ProviderContext<'_>,
180	    name: &TagName,
181	) -> Result<Attempt<RemoteTagObservation>, GraphError> {
182	    let endpoint = context.checked_git_remote()?.endpoint.clone();
183	    let reference = format!("refs/tags/{name}");
184	    // The peeled ref resolves an annotated tag to its commit; a lightweight
185	    // tag has no peeled line at all.
186	    let peeled = format!("{reference}^{{}}");
187	    let args = ["ls-remote", endpoint.as_str(), reference.as_str(), peeled.as_str()];
188	    let observed = match run_observation(
189	        context.runner(),
190	        programs::GIT,
191	        &args,
192	        context.root(),
193	        timeouts::GIT_LS_REMOTE,
194	        true,
195	    )? {
196	        Ok(observed) => observed,
197	        Err(_unavailable) => {
198	            return Ok(Attempt::Transient {
199	                value: RemoteTagObservation::Indeterminate,
200	                retry_after: None,
201	            })
202	        }
203	    };
204	    if observed.exit_code != Some(0) {
205	        return Ok(Attempt::Transient {
206	            value: RemoteTagObservation::Indeterminate,
207	            retry_after: None,
208	        });
209	    }
210	    classify_ls_remote(&observed.stdout, &reference, &peeled, &args).map(Attempt::Settled)
