    98	/// GitHub's refusal when an App token pushes a ref whose tree's workflows
    99	/// differ from every branch tip.
   100	const WORKFLOW_GUARD_REFUSAL: &str = "refusing to allow a GitHub App to create or update workflow";
   101	
   102	fn push_tag(
   103	    runner: &dyn CommandRunner,
   104	    root: &Path,
   105	    endpoint: &str,
   106	    operation: &TagOperation,
   107	) -> Result<(), GraphError> {
   108	    let push_args = ["push", endpoint, operation.name.as_str()];
   109	    let pushed = runner.run_with_timeout(programs::GIT, &push_args, root, timeouts::GIT_PUSH)?;
   110	    if pushed.exit_code == Some(0) {
   111	        return Ok(());
   112	    }
   113	    if pushed.stderr.contains(WORKFLOW_GUARD_REFUSAL) {
   114	        return Err(GraphError::ReleaseTagPushRefusedWorkflowGuard {
   115	            tag: operation.name.as_str().to_owned(),
   116	            target: operation.target.as_str().to_owned(),
   117	        });
   118	    }
   119	    Err(GraphError::ReleaseCommand {
   120	        program: programs::GIT.to_string(),
   121	        args: push_args.iter().map(ToString::to_string).collect(),
   122	        failure: CommandFailure::NonZeroExit {
   123	            exit_code: pushed.exit_code,
   124	            stderr: pushed.stderr,
   125	        },
   126	    })
   127	}
