   136	/// The remote decides whether the tag operation is satisfied, but a local
   137	/// ref that contradicts the prepared tag is still a conflict: the next push
   138	/// would carry it.
   139	fn tag_observation(
   140	    context: &ProviderContext<'_>,
   141	    operation: &TagOperation,
   142	) -> Result<ProviderObservationV1, GraphError> {
   143	    match observed_local_tag(context, &operation.name)? {
   144	        LocalTagObservation::Absent => {}
   145	        LocalTagObservation::Annotated { target: observed } if observed == operation.target => {}
   146	        _ => {
   147	            return Ok(ProviderObservationV1::Conflict {
   148	                reason: ProviderConflictReason::LocalTagDiffers,
   149	            })
   150	        }
   151	    }
   152	    let remote = policy::retry_observation(context.sleeper(), || observed_remote_tag(context, &operation.name))?;
   153	    Ok(match remote {
   154	        RemoteTagObservation::Absent => ProviderObservationV1::Absent,
   155	        RemoteTagObservation::Annotated { target: observed } if observed == operation.target => {
   156	            ProviderObservationV1::Exact {
   157	                evidence: ProviderEvidenceV1::GitTag {
   158	                    peeled_commit: observed,
   159	                },
   160	            }
   161	        }
   162	        RemoteTagObservation::Annotated { .. } => ProviderObservationV1::Conflict {
   163	            reason: ProviderConflictReason::RemoteTagTargetDiffers,
   164	        },
   165	        RemoteTagObservation::Unannotated => ProviderObservationV1::Conflict {
   166	            reason: ProviderConflictReason::UnannotatedTag,
   167	        },
   168	        RemoteTagObservation::Indeterminate => ProviderObservationV1::Indeterminate {
   169	            cause: ProviderIndeterminateCause::CommandFailed,
   170	        },
   171	    })
   172	}
   173	
   174	/// Observes `refs/tags/<name>` on the prepared remote. A git failure leaves
   175	/// the remote unknown; absence must be proved by a successful query. The
   176	/// failure is transient: `ls-remote` is a read, so retrying it cannot have an
   177	/// effect.
   178	fn observed_remote_tag(
   179	    context: &ProviderContext<'_>,
   180	    name: &TagName,
   181	) -> Result<Attempt<RemoteTagObservation>, GraphError> {
   182	    let endpoint = context.checked_git_remote()?.endpoint.clone();
   183	    let reference = format!("refs/tags/{name}");
   184	    // The peeled ref resolves an annotated tag to its commit; a lightweight
   185	    // tag has no peeled line at all.
   186	    let peeled = format!("{reference}^{{}}");
   187	    let args = ["ls-remote", endpoint.as_str(), reference.as_str(), peeled.as_str()];
   188	    let observed = match run_observation(
   189	        context.runner(),
   190	        programs::GIT,
   191	        &args,
   192	        context.root(),
   193	        timeouts::GIT_LS_REMOTE,
   194	        true,
   195	    )? {
   196	        Ok(observed) => observed,
   197	        Err(_unavailable) => {
   198	            return Ok(Attempt::Transient {
   199	                value: RemoteTagObservation::Indeterminate,
   200	                retry_after: None,
   201	            })
   202	        }
   203	    };
   204	    if observed.exit_code != Some(0) {
   205	        return Ok(Attempt::Transient {
   206	            value: RemoteTagObservation::Indeterminate,
   207	            retry_after: None,
   208	        });
   209	    }
   210	    classify_ls_remote(&observed.stdout, &reference, &peeled, &args).map(Attempt::Settled)
   211	}
   212	
   213	/// Reads `ls-remote` output for `reference` and its peeled `^{}` form.
   214	fn classify_ls_remote(
   215	    stdout: &str,
   216	    reference: &str,
   217	    peeled: &str,
   218	    args: &[&str],
   219	) -> Result<RemoteTagObservation, GraphError> {
   220	    let mut tag_object = None;
   221	    let mut peeled_commit = None;
   222	    for line in stdout.lines() {
   223	        let Some((sha, found)) = line.split_once('\t') else {
   224	            continue;
   225	        };
   226	        match found.trim() {
   227	            found if found == peeled => peeled_commit = Some(sha),
   228	            found if found == reference => tag_object = Some(sha),
   229	            _ => {}
   230	        }
   231	    }
   232	    let Some(sha) = peeled_commit.or(tag_object) else {
   233	        return Ok(RemoteTagObservation::Absent);
   234	    };
   235	    if peeled_commit.is_none() {
   236	        return Ok(RemoteTagObservation::Unannotated);
   237	    }
   238	    let target = CommitSha::parse(sha.trim()).map_err(|error| GraphError::ReleaseCommand {
   239	        program: programs::GIT.to_string(),
   240	        args: args.iter().map(ToString::to_string).collect(),
   241	        failure: CommandFailure::MalformedOutput {
   242	            detail: error.to_string(),
   243	        },
   244	    })?;
   245	    Ok(RemoteTagObservation::Annotated { target })
   246	}
   247	
   248	fn observed_local_tag(context: &ProviderContext<'_>, name: &TagName) -> Result<LocalTagObservation, GraphError> {
   249	    let reference = format!("refs/tags/{name}^{{commit}}");
   250	    let rev_parse_args = ["rev-parse", "--verify", "--quiet", reference.as_str()];
   251	    let observed =
   252	        context
   253	            .runner()
   254	            .run_with_timeout(programs::GIT, &rev_parse_args, context.root(), timeouts::LOCAL_GIT)?;
   255	    if observed.exit_code != Some(0) {
   256	        return Ok(LocalTagObservation::Absent);
   257	    }
   258	    let target = CommitSha::parse(observed.stdout.trim()).map_err(|error| GraphError::ReleaseCommand {
   259	        program: programs::GIT.to_string(),
   260	        args: rev_parse_args.iter().map(ToString::to_string).collect(),
   261	        failure: CommandFailure::MalformedOutput {
   262	            detail: error.to_string(),
   263	        },
   264	    })?;
   265	    let for_each_ref_target = format!("refs/tags/{name}");
   266	    let for_each_ref_args = [
   267	        "for-each-ref",
   268	        "--format=%(objecttype)%00%(contents:subject)%00%(contents:body)",
   269	        for_each_ref_target.as_str(),
   270	    ];
"}}

