557	/// Maps a non-zero exit to `GraphError::LockfileRefreshFailed`, an exec failure to `GraphError::Command`.
558	fn run_lockfile_refresh<R: CommandRunner>(
559	    runner: &R,
560	    root: &Path,
561	    filename: &str,
562	    program: &str,
563	    args: &[&str],
564	) -> Result<LockfileRefreshResult, GraphError> {
565	    let refresh_command = format!("{program} {}", args.join(" "));
566	    let out = runner.run(program, args, root)?;
567	    if !out.success() {
568	        return Err(GraphError::LockfileRefreshFailed {
569	            filename: PathBuf::from(filename),
570	            refresh_command,
571	            exit_code: out.exit_code,
572	            stderr: out.redacted_stderr(),
573	        });
574	    }
575	    Ok(LockfileRefreshResult {
576	        filename: PathBuf::from(filename),
577	        refresh_command,
578	        success: true,
579	        exit_code: out.exit_code,
580	    })
581	}
