  8	pub fn plan_snapshot<R: CommandRunner, D: DependencyResolver>(
  9	    ws: &Workspace<'_, R, D>,
 10	    tag: &str,
 11	) -> Result<(VersionPlan, SnapshotReport), GraphError> {
 12	    // Resolve HEAD for real rather than faking it, so unrelated snapshot runs never collide.
 13	    let sha = ws.git_access().head_sha()?;
 14	    let sha_short = sha.short();
 15	
 16	    // Label for the report only; each package's actual version is built in its own grammar below.
 17	    let snapshot_tag = format!("0.0.0-{tag}-{sha_short}");
 18	    let base_versions = ws.base_versions()?;
 19	    // No severity cascade to seed here; `ws.tags()` only checks the propagate-failure invariant below.
 20	    ws.tags()?;
 21	
 22	    let mut bumps = Vec::new();
 23	    let mut plan_bumps = Vec::new();
 24	
 25	    let mut snapshot_versions = std::collections::BTreeMap::new();
 26	
 27	    for pkg in ws.graph.packages() {
 28	        let from = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
 29	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
