  1	use std::path::PathBuf;
  2	
  3	use callisto_model::vcs::GitAccess;
  4	use callisto_model::{CommitSha, Package, Severity, Version};
  5	
  6	use crate::config::PreMajorInferencePolicy;
  7	use crate::error::GraphError;
  8	
  9	pub trait SeverityInference: Send + Sync {
 10	    /// `git` is the caller's already-discovered [`GitAccess`] (e.g.
 11	    /// `aggregate()`'s own parameter, itself `Workspace`-shared) -- an impl
 12	    /// that needs commit history must use this rather than discovering its
 13	    /// own, so an N-package workspace pays for one discovery, not N.
 14	    fn infer(
 15	        &self,
 16	        pkg: &Package,
 17	        git: &GitAccess<'_>,
 18	        window: InferenceWindowSpec<'_>,
 19	    ) -> Result<Option<InferenceOutcome>, GraphError>;
 20	}
 21	
 22	pub struct InferenceWindowSpec<'a> {
 23	    pub pathspecs: &'a [PathBuf],
 24	    pub since: Option<CommitSha>,
 25	    pub current_version: &'a Version,
 26	    pub has_prior_release: bool,
 27	    pub policy: PreMajorInferencePolicy,
 28	}
 29	
 30	#[derive(Clone, Debug, PartialEq, Eq)]
 31	pub struct InferenceOutcome {
 32	    pub severity: Severity,
 33	    pub commit_count: usize,
 34	    pub remapped: bool,
 35	    pub commits: Vec<(CommitSha, String)>,
 36	}
 37	
 38	pub struct NoInference;
 39	
 40	impl SeverityInference for NoInference {
 41	    fn infer(
 42	        &self,
 43	        _pkg: &Package,
 44	        _git: &GitAccess<'_>,
 45	        _window: InferenceWindowSpec<'_>,
 46	    ) -> Result<Option<InferenceOutcome>, GraphError> {
 47	        Ok(None)
 48	    }
 49	}
 50	
 51	/// The shipped impl. A thin, stateless adapter over
 52	/// `crate::conventional::infer_severity` -- it holds no fields of its own; the caller's
 53	/// [`GitAccess`] is handed in per call via [`SeverityInference::infer`]'s `git` parameter
 54	/// rather than discovered here, so this type carries nothing to discover it with.
 55	pub struct CommitInference;
 56	
 57	impl SeverityInference for CommitInference {
 58	    fn infer(
 59	        &self,
 60	        pkg: &Package,
 61	        git: &GitAccess<'_>,
 62	        window: InferenceWindowSpec<'_>,
 63	    ) -> Result<Option<InferenceOutcome>, GraphError> {
 64	        use crate::conventional::{infer_severity, InferenceInput, InferenceWindow};
 65	
 66	        let inf_window = match window.since {
 67	            Some(sha) => InferenceWindow::SinceCommit(sha),
 68	            None => InferenceWindow::FullHistory,
 69	        };
 70	
 71	        let input = InferenceInput {
 72	            package: &pkg.id,
 73	            pathspecs: window.pathspecs,
 74	            window: inf_window,
 75	            current_version: window.current_version,
 76	            has_prior_release: window.has_prior_release,
 77	        };
 78	
 79	        // Selecting the VCS backend is this layer's job: `conventional`
 80	        // takes any `callisto_model::CommitWalker` and never names a VCS crate.
 81	        let raw = infer_severity(git, &input)?;
 82	        if raw.commit_count == 0 {
 83	            return Ok(None);
 84	        }
 85	
 86	        let (severity, remapped) = crate::aggregate::apply_pre_major(
 87	            raw.severity,
 88	            window.policy,
 89	            window.current_version,
 90	            window.has_prior_release,
 91	        );
 92	
 93	        let commits = raw
 94	            .commits
 95	            .into_iter()
 96	            .map(|c| (c.sha().clone(), c.subject().to_string()))
 97	            .collect();
 98	
 99	        Ok(Some(InferenceOutcome {
100	            severity,
101	            commit_count: raw.commit_count,
102	            remapped,
103	            commits,
104	        }))
105	    }
106	}

