421	    fn update_dependency_spec(
422	        &mut self,
423	        name: &str,
424	        kind: DepKind,
425	        new: DepSpec,
426	        _permit: &ApplyPermit,
427	    ) -> Result<(), ManifestError> {
428	        if kind == DepKind::Build {
429	            return Err(ManifestError::DependencyNotFound {
430	                path: self.path.clone(),
431	                name: name.to_string(),
432	                kind,
433	            });
434	        }
435	
436	        let section_name = match kind {
437	            DepKind::Runtime => "dependencies",
438	            DepKind::Dev => "devDependencies",
439	            DepKind::Peer => "peerDependencies",
440	            DepKind::Optional => "optionalDependencies",
441	            DepKind::Build => unreachable!(),
442	        };
443	
444	        // Validate that the target dependency actually exists in the primary
445	        // section *before* mutating anything. This guarantees that a failed
446	        // update (dependency not found) leaves self.doc byte-for-byte
447	        // unchanged, including the overrides/resolutions tables below.
448	        let updated_in_section = self
449	            .doc
450	            .get(section_name)
451	            .and_then(|v| v.as_object())
452	            .is_some_and(|section| section.contains_key(name));
453	
454	        if !updated_in_section {
455	            return Err(ManifestError::DependencyNotFound {
456	                path: self.path.clone(),
457	                name: name.to_string(),
458	                kind,
459	            });
460	        }
461	
462	        if let Some(section) = self.doc.get_mut(section_name).and_then(|v| v.as_object_mut()) {
463	            section.insert(name.to_string(), Value::String(new.render()));
464	        }
465	
466	        for extra in ["overrides", "resolutions"] {
467	            if let Some(tbl) = self.doc.get_mut(extra).and_then(|v| v.as_object_mut()) {
468	                if tbl.get(name).is_some_and(|v| v.is_string()) {
469	                    tbl.insert(name.to_string(), Value::String(new.render()));
470	                }
471	            }
472	        }
473	
474	        Ok(())
475	    }
