 3	use callisto_cli::cli::{AddArgs, GlobalArgs, OutputFormat, VersionArgs};
 4	use callisto_cli::commands;
 5	
 6	use common::setup_polyglot_git_repo;
 7	
 8	/// Two `version` runs with nothing committed between them must refuse the second (E121), not stack a second bump.
 9	#[test]
10	fn test_version_twice_without_commit_is_refused_as_partial_run() {
11	    let dir = setup_polyglot_git_repo();
12	    let root = dir.path();
13	
14	    let global = GlobalArgs {
15	        format: OutputFormat::Json,
16	        cwd: root.to_path_buf(),
17	        dry_run: false,
18	    };
19	
20	    callisto_fixtures::scaffold_callisto(&global.cwd);
21	
22	    commands::add::handle(
23	        AddArgs {
24	            packages: vec!["core-crate:patch".to_string()],
25	            summary: Some("Fix the frobnication bug".to_string()),
26	        },
27	        &global,
28	    )
29	    .unwrap();
30	
31	    commands::version::handle(
32	        VersionArgs {
33	            refresh_lockfiles: false,
34	            no_refresh_lockfiles: true,
35	            strict: false,
36	            allow_empty_changesets: false,
37	            emit_decision: None,
38	        },
39	        &global,
40	    )
41	    .expect("the first version run must succeed and stage its changes");
42	
43	    let second = commands::version::handle(
44	        VersionArgs {
45	            refresh_lockfiles: false,
46	            no_refresh_lockfiles: true,
47	            strict: false,
48	            allow_empty_changesets: false,
49	            emit_decision: None,
50	        },
51	        &global,
52	    );
53	
54	    assert!(
55	        second.is_err(),
56	        "a second `version` run with nothing committed since the first must be refused, not \
57	         silently apply a second bump on top of the first uncommitted one"
58	    );
59	    let message = second.unwrap_err().to_string();
60	    assert!(
61	        message.contains("this looks like a `version` run that wrote and staged its changes but never committed")
62	            || message.contains("E121"),
63	        "expected the partial-run (E121) refusal, got: {message}"
64	    );
65	}

