  6	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
  7	#[serde(rename_all = "camelCase")]
  8	pub struct PreState {
  9	    pub mode: PreMode,
 10	    pub tag: String,
