115	pub fn write_pre_json(state: &PreState) -> String {
116	    render_pre_json(state, "  ")
117	}
118	
119	/// Renders `state`, then reapplies `existing`'s on-disk formatting (BOM, CRLF vs LF, indent width) instead of the
120	/// default 2-space bare-LF shape, so a CRLF or custom-indent `pre.json` (e.g. `core.autocrlf=true`, or hand-edited)
121	/// is not reformatted on a `pre exit` or mid-cycle `version` rewrite.
122	pub fn write_pre_json_preserving(state: &PreState, existing: &str) -> String {
123	    let fp = PreJsonFingerprint::detect(existing);
124	    let rendered = render_pre_json(state, &fp.indent_str());
125	    fp.apply(&rendered)
126	}
127	
128	fn render_pre_json(state: &PreState, indent_str: &str) -> String {
129	    let mut map = IndexMap::new();
130	    map.insert("mode".to_string(), serde_json::to_value(state.mode).unwrap());
131	    map.insert("tag".to_string(), serde_json::to_value(&state.tag).unwrap());
132	
133	    let mut init_map = IndexMap::new();
134	    for (pkg, ver) in &state.initial_versions {
135	        init_map.insert(pkg.clone(), serde_json::to_value(ver).unwrap());
136	    }
137	    map.insert("initialVersions".to_string(), serde_json::to_value(init_map).unwrap());
138	    map.insert(
139	        "changesets".to_string(),
140	        serde_json::to_value(&state.changesets).unwrap(),
141	    );
142	
143	    let formatter = serde_json::ser::PrettyFormatter::with_indent(indent_str.as_bytes());
144	    let mut buf = Vec::new();
145	    let mut serializer = serde_json::Serializer::with_formatter(&mut buf, formatter);
146	    serde::Serialize::serialize(&map, &mut serializer).unwrap();
147	    let mut out = String::from_utf8(buf).unwrap();
148	    out.push('\n');
149	    out
150	}
