152	/// Byte-level formatting facts (BOM, CRLF, indent) `pre.json` must preserve across a rewrite.
153	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
154	struct PreJsonFingerprint {
155	    has_bom: bool,
156	    crlf: bool,
157	    indent: PreJsonIndent,
158	}
159	
160	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
161	enum PreJsonIndent {
162	    Spaces(u8),
163	    Tabs,
164	}
165	
166	impl PreJsonFingerprint {
167	    fn detect(content: &str) -> Self {
168	        let has_bom = content.starts_with('\u{FEFF}');
169	        let clean = content.strip_prefix('\u{FEFF}').unwrap_or(content);
170	        let crlf = clean.contains("\r\n");
171	
172	        // The first quote-leading line is a top-level key at indent depth 1; its leading whitespace is one unit.
173	        let mut indent = PreJsonIndent::Spaces(2);
174	        for line in clean.lines() {
175	            let trimmed = line.trim_start();
176	            if trimmed.starts_with('"') && line.len() > trimmed.len() {
177	                let leading = &line[..line.len() - trimmed.len()];
178	                indent = if leading.contains('\t') {
179	                    PreJsonIndent::Tabs
180	                } else {
181	                    PreJsonIndent::Spaces(leading.len() as u8)
182	                };
183	                break;
184	            }
185	        }
186	
187	        PreJsonFingerprint { has_bom, crlf, indent }
188	    }
189	
190	    fn indent_str(&self) -> String {
191	        match self.indent {
192	            PreJsonIndent::Tabs => "\t".to_string(),
193	            PreJsonIndent::Spaces(n) => " ".repeat(n as usize),
194	        }
195	    }
196	
197	    /// Reapplies this fingerprint to `rendered`, a freshly-serialized body with bare-LF endings and no BOM.
198	    fn apply(&self, rendered: &str) -> String {
199	        let mut out = if self.crlf {
200	            rendered.replace("\r\n", "\n").replace('\n', "\r\n")
201	        } else {
202	            rendered.to_string()
203	        };
204	        if self.has_bom {
205	            out = format!("\u{FEFF}{out}");
206	        }
207	        out
208	    }
209	}
