211	#[derive(Debug, thiserror::Error, Clone, PartialEq, Eq)]
212	#[non_exhaustive]
213	pub enum PreJsonError {
214	    #[error("pre.json is not a valid JSON object: {message}")]
215	    Malformed { message: String },
216	
217	    #[error("pre.json is missing required field {field:?}")]
218	    MissingField { field: &'static str },
219	
220	    #[error("pre.json field {field:?} has the wrong type")]
221	    WrongFieldType { field: &'static str },
222	
223	    #[error("pre.json has mode {found:?}, expected \"pre\" or \"exit\"")]
224	    InvalidMode { found: String },
225	
226	    #[error("pre.json initialVersions[{package:?}] = {raw:?} is not a valid version: {source}")]
227	    InvalidInitialVersion {
228	        package: String,
229	        raw: String,
230	        #[source]
231	        source: crate::VersionParseError,
232	    },
233	
