123	impl Versioning for Pep440Versioning {
124	    fn grammar(&self) -> VersionGrammar {
125	        VersionGrammar::Pep440
126	    }
127	
128	    fn bump(&self, current: &Version, severity: Severity) -> Result<Version, BumpError> {
129	        if current.grammar() != VersionGrammar::Pep440 {
130	            return Err(BumpError::NotPep440 {
131	                raw: current.render().to_string(),
132	                grammar: current.grammar(),
133	            });
134	        }
135	
136	        if severity == Severity::None {
137	            return Ok(current.clone());
138	        }
139	
140	        let parsed = parse_pep440(current)?;
141	        let epoch = parsed.epoch();
142	        let (major, minor, patch) = release_triple(&parsed);
143	
144	        // Pre-releases and dev-releases both precede the release they're attached
145	        // to, so a bump finalizes them in place rather than continuing forward.
146	        // But a post-release segment (even combined with a dev segment, e.g.
147	        // `1.2.3.post1.dev1`) outranks the final release (PEP 440 ordering:
148	        // dev < pre < release < post), so any version carrying a post segment
149	        // must bump forward normally, same as the post-only case, never
150	        // finalize in place.
151	        let finalize_in_place = !parsed.is_post() && (parsed.is_pre() || parsed.is_dev());
152	
153	        let overflow = || BumpError::Overflow {
154	            raw: current.render().to_string(),
155	        };
156	
157	        let (new_major, new_minor, new_patch) =
158	            bump_release_triple(major, minor, patch, severity, finalize_in_place, overflow)?;
159	
160	        let bumped = pep440_rs::Version::new([new_major, new_minor, new_patch]).with_epoch(epoch);
161	        render_pep440(bumped)
162	    }
163	
164	    fn bump_prerelease(
165	        &self,
166	        base: &Version,
167	        severity: Severity,
168	        tag: &str,
169	        current: &Version,
170	    ) -> Result<Version, BumpError> {
171	        if severity == Severity::None {
172	            return Ok(current.clone());
173	        }
174	
175	        let release = self.bump(base, severity)?;
176	        let release_str = release.render();
177	
178	        // PEP 440 pre-release labels are restricted to alpha/beta/rc; an arbitrary
179	        // caller-supplied tag (e.g. "next") has no PEP 440 equivalent, so it falls
180	        // back to a dev-release, the closest "not yet final" concept PEP 440 has.
181	        let letter = pep440_prerelease_letter(tag);
182	
183	        let overflow = || BumpError::Overflow {
184	            raw: current.render().to_string(),
185	        };
186	        let current_raw = current.render();
187	        let counter_suffix = current_raw.strip_prefix(release_str).and_then(|rest| match letter {
188	            Some(letter) => rest.strip_prefix(letter),
189	            None => rest.strip_prefix(".dev"),
190	        });
191	        let counter = next_counter(counter_suffix, overflow)?;
192	
193	        let prerelease_str = match letter {
194	            Some(letter) => format!("{release_str}{letter}{counter}"),
195	            None => format!("{release_str}.dev{counter}"),
196	        };
197	
198	        Version::parse(&prerelease_str, VersionGrammar::Pep440).map_err(|e| BumpError::ComputedVersionInvalid {
199	            raw: prerelease_str,
200	            message: e.message,
201	        })
202	    }
203	}
204	
205	/// Maps common pre-release tag spellings to their PEP 440 letter. PEP 440 only
206	/// recognizes alpha/beta/rc pre-releases; anything else has no direct mapping.
207	fn pep440_prerelease_letter(tag: &str) -> Option<&'static str> {
208	    match tag.to_ascii_lowercase().as_str() {
209	        "a" | "alpha" => Some("a"),
210	        "b" | "beta" => Some("b"),
211	        "rc" | "c" | "pre" | "preview" => Some("rc"),
212	        _ => None,
213	    }
214	}
215	
216	fn parse_pep440(v: &Version) -> Result<pep440_rs::Version, BumpError> {
217	    v.raw()
218	        .parse::<pep440_rs::Version>()
219	        .map_err(|e| BumpError::ComputedVersionInvalid {
220	            raw: v.raw().to_string(),
221	            message: e.to_string(),
222	        })
223	}
224	
225	fn release_triple(v: &pep440_rs::Version) -> (u64, u64, u64) {
226	    let release = v.release();
227	    (
228	        release.first().copied().unwrap_or(0),
229	        release.get(1).copied().unwrap_or(0),
230	        release.get(2).copied().unwrap_or(0),
231	    )
232	}
233	
234	fn render_pep440(v: pep440_rs::Version) -> Result<Version, BumpError> {
235	    let rendered = v.to_string();
236	    Version::parse(&rendered, VersionGrammar::Pep440).map_err(|e| BumpError::ComputedVersionInvalid {
237	        raw: rendered,
238	        message: e.message,
239	    })
240	}
