284	/// Parses `suffix` (text after a stripped tag/letter prefix) as the existing
285	/// prerelease counter and returns it incremented; `None` or non-numeric
286	/// means "no matching prefix", so counting starts fresh at 0.
287	fn next_counter(suffix: Option<&str>, overflow: impl Fn() -> BumpError) -> Result<u64, BumpError> {
288	    match suffix.and_then(|s| s.parse::<u64>().ok()) {
289	        Some(num) => num.checked_add(1).ok_or_else(overflow),
290	        None => Ok(0),
291	    }
292	}
