299	#[non_exhaustive]
300	pub enum BumpError {
301	    #[error("bump_version requires a SemVer version; `{raw}` was parsed as {grammar:?}")]
302	    #[diagnostic(code(E035))]
303	    NotSemVer { raw: String, grammar: VersionGrammar },
304	    #[error("no versioning implementation exists for {grammar:?}")]
305	    #[diagnostic(code(E036))]
306	    UnsupportedGrammar { grammar: VersionGrammar },
307	    #[error("bump requires a PEP 440 version; `{raw}` was parsed as {grammar:?}")]
308	    #[diagnostic(code(E037))]
309	    NotPep440 { raw: String, grammar: VersionGrammar },
310	    #[error("internal error computing bumped version `{raw}`: {message}")]
311	    #[diagnostic(code(E038))]
312	    ComputedVersionInvalid { raw: String, message: String },
313	    #[error("version component overflow while bumping `{raw}`")]
314	    #[diagnostic(code(E039))]
315	    Overflow { raw: String },
316	}
