 49	impl Versioning for SemVerVersioning {
 50	    fn grammar(&self) -> VersionGrammar {
 51	        VersionGrammar::SemVer
 52	    }
 53	
 54	    fn bump(&self, current: &Version, severity: Severity) -> Result<Version, BumpError> {
 55	        if current.grammar() != VersionGrammar::SemVer {
 56	            return Err(BumpError::NotSemVer {
 57	                raw: current.render().to_string(),
 58	                grammar: current.grammar(),
 59	            });
 60	        }
 61	
 62	        if severity == Severity::None {
 63	            return Ok(current.clone());
 64	        }
 65	
 66	        let major = current.major().unwrap_or(0);
 67	        let minor = current.minor().unwrap_or(0);
 68	        let patch = current.patch().unwrap_or(0);
 69	
 70	        let overflow = || BumpError::Overflow {
 71	            raw: current.render().to_string(),
 72	        };
 73	
 74	        let (new_major, new_minor, new_patch) =
 75	            bump_release_triple(major, minor, patch, severity, current.is_prerelease(), overflow)?;
 76	
 77	        Ok(Version::semver(new_major, new_minor, new_patch))
 78	    }
 79	
 80	    fn bump_prerelease(
 81	        &self,
 82	        base: &Version,
 83	        severity: Severity,
 84	        tag: &str,
 85	        current: &Version,
 86	    ) -> Result<Version, BumpError> {
 87	        if severity == Severity::None {
 88	            return Ok(current.clone());
 89	        }
 90	
 91	        let release = self.bump(base, severity)?;
 92	        let overflow = || BumpError::Overflow {
 93	            raw: current.render().to_string(),
 94	        };
 95	
 96	        let mut counter_suffix = None;
 97	        if current.is_prerelease() {
 98	            let current_raw = current.render();
 99	            if let Some((rel_part, pre_part)) = current_raw.split_once('-') {
100	                if rel_part == release.render() {
101	                    let dotted_prefix = format!("{tag}.");
102	                    counter_suffix = pre_part
103	                        // Dotted form: e.g. "alpha.3" with tag "alpha" → "3"
104	                        .strip_prefix(&dotted_prefix)
105	                        // Undotted form: e.g. "alpha1" with tag "alpha" → "1"
106	                        .or_else(|| pre_part.strip_prefix(tag));
107	                }
108	            }
109	        }
110	        let counter = next_counter(counter_suffix, overflow)?;
111	
112	        let prerelease_str = format!("{}-{tag}.{counter}", release.render());
113	        let final_version =
114	            Version::parse(&prerelease_str, VersionGrammar::SemVer).map_err(|_err| BumpError::NotSemVer {
115	                raw: prerelease_str,
116	                grammar: VersionGrammar::SemVer,
117	            })?;
118	
119	        Ok(final_version)
120	    }
121	}
