123	impl Versioning for Pep440Versioning {
124	    fn grammar(&self) -> VersionGrammar {
125	        VersionGrammar::Pep440
126	    }
127	
128	    fn bump(&self, current: &Version, severity: Severity) -> Result<Version, BumpError> {
129	        if current.grammar() != VersionGrammar::Pep440 {
130	            return Err(BumpError::NotPep440 {
131	                raw: current.render().to_string(),
132	                grammar: current.grammar(),
133	            });
134	        }
135	
136	        if severity == Severity::None {
137	            return Ok(current.clone());
138	        }
139	
140	        let parsed = parse_pep440(current)?;
141	        let epoch = parsed.epoch();
142	        let (major, minor, patch) = release_triple(&parsed);
143	
144	        // Pre-releases and dev-releases both precede the release they're attached
145	        // to, so a bump finalizes them in place rather than continuing forward.
146	        // But a post-release segment (even combined with a dev segment, e.g.
147	        // `1.2.3.post1.dev1`) outranks the final release (PEP 440 ordering:
148	        // dev < pre < release < post), so any version carrying a post segment
149	        // must bump forward normally, same as the post-only case, never
150	        // finalize in place.
151	        let finalize_in_place = !parsed.is_post() && (parsed.is_pre() || parsed.is_dev());
152	
153	        let overflow = || BumpError::Overflow {
154	            raw: current.render().to_string(),
155	        };
156	
157	        let (new_major, new_minor, new_patch) =
158	            bump_release_triple(major, minor, patch, severity, finalize_in_place, overflow)?;
159	
160	        let bumped = pep440_rs::Version::new([new_major, new_minor, new_patch]).with_epoch(epoch);
161	        render_pep440(bumped)
162	    }
