164	    fn bump_prerelease(
165	        &self,
166	        base: &Version,
167	        severity: Severity,
168	        tag: &str,
169	        current: &Version,
170	    ) -> Result<Version, BumpError> {
171	        if severity == Severity::None {
172	            return Ok(current.clone());
173	        }
174	
175	        let release = self.bump(base, severity)?;
176	        let release_str = release.render();
177	
178	        // PEP 440 pre-release labels are restricted to alpha/beta/rc; an arbitrary
179	        // caller-supplied tag (e.g. "next") has no PEP 440 equivalent, so it falls
180	        // back to a dev-release, the closest "not yet final" concept PEP 440 has.
181	        let letter = pep440_prerelease_letter(tag);
182	
183	        let overflow = || BumpError::Overflow {
184	            raw: current.render().to_string(),
185	        };
186	        let current_raw = current.render();
187	        let counter_suffix = current_raw.strip_prefix(release_str).and_then(|rest| match letter {
188	            Some(letter) => rest.strip_prefix(letter),
189	            None => rest.strip_prefix(".dev"),
190	        });
191	        let counter = next_counter(counter_suffix, overflow)?;
192	
193	        let prerelease_str = match letter {
194	            Some(letter) => format!("{release_str}{letter}{counter}"),
195	            None => format!("{release_str}.dev{counter}"),
196	        };
197	
198	        Version::parse(&prerelease_str, VersionGrammar::Pep440).map_err(|e| BumpError::ComputedVersionInvalid {
199	            raw: prerelease_str,
200	            message: e.message,
201	        })
202	    }
203	}
