{"cmd":"rtk proxy sed -n '80,115p' crates/callisto-graph/src/groups.rs","chunk_id":"8a0b7d","wall_time_seconds":0.000009209,"exit_code":0,"original_token_count":413,"output":"/// Computes `base`'s next version under `severity`, grammar-aware (SemVer vs PEP 440) and, in pre-release mode,
/// anchored on `pre.json`'s pinned `initialVersions` entry rather than the live on-disk version. Shared by
/// `cascade::bump_target` and `fixed_group_target`, and rejects any result that sorts behind `base`.
pub fn versioned_bump(
    package: &PackageId,
    base: &Version,
    severity: Severity,
    pre: Option<&callisto_model::format::PreState>,
) -> Result<Version, GraphError> {
    let versioning = callisto_model::format::versioning_for(base.grammar())
        .ok_or(callisto_model::format::BumpError::UnsupportedGrammar {
            grammar: base.grammar(),
        })
        .map_err(GraphError::Bump)?;

    // Compares against the pinned anchor in pre mode, not live on-disk, which may lead a different pre-release cycle.
    let (bumped_from, next) = match pre {
        Some(pre) if pre.mode == callisto_model::format::PreMode::Pre => {
            let pinned_base = crate::pre_initial_version(pre, package).unwrap_or(base);
            let next = versioning
                .bump_prerelease(pinned_base, severity, &pre.tag, base)
                .map_err(GraphError::Bump)?;
            (pinned_base.clone(), next)
        }
        _ => {
            let next = versioning.bump(base, severity).map_err(GraphError::Bump)?;
            (base.clone(), next)
        }
    };

    if matches!(Version::compare(&next, &bumped_from), Ok(std::cmp::Ordering::Less)) {
        return Err(GraphError::VersionRegression {
            package: package.clone(),
            from: bumped_from,
            to: next,
        });
"}

