216	fn parse_pep440(v: &Version) -> Result<pep440_rs::Version, BumpError> {
217	    v.raw()
218	        .parse::<pep440_rs::Version>()
219	        .map_err(|e| BumpError::ComputedVersionInvalid {
220	            raw: v.raw().to_string(),
221	            message: e.to_string(),
222	        })
223	}
224	
225	fn release_triple(v: &pep440_rs::Version) -> (u64, u64, u64) {
226	    let release = v.release();
227	    (
228	        release.first().copied().unwrap_or(0),
229	        release.get(1).copied().unwrap_or(0),
230	        release.get(2).copied().unwrap_or(0),
231	    )
232	}
233	
234	fn render_pep440(v: pep440_rs::Version) -> Result<Version, BumpError> {
235	    let rendered = v.to_string();
236	    Version::parse(&rendered, VersionGrammar::Pep440).map_err(|e| BumpError::ComputedVersionInvalid {
237	        raw: rendered,
238	        message: e.message,
239	    })
240	}
