242	/// Shared major.minor.patch bump arithmetic for SemVer and PEP 440.
243	/// `finalize_in_place=true` finalizes an in-place pre/dev tag toward the base
244	/// release (advancing the next component up only when the lower one(s) are
245	/// already zero); `false` bumps the target component forward normally.
246	/// Severity::None is unreachable -- callers return early on it before this.
247	fn bump_release_triple(
248	    major: u64,
249	    minor: u64,
250	    patch: u64,
251	    severity: Severity,
252	    finalize_in_place: bool,
253	    overflow: impl Fn() -> BumpError,
254	) -> Result<(u64, u64, u64), BumpError> {
255	    if finalize_in_place {
256	        match severity {
257	            Severity::Patch => Ok((major, minor, patch)),
258	            Severity::Minor => {
259	                if patch == 0 {
260	                    Ok((major, minor, patch))
261	                } else {
262	                    Ok((major, minor.checked_add(1).ok_or_else(overflow)?, 0))
263	                }
264	            }
265	            Severity::Major => {
266	                if minor == 0 && patch == 0 {
267	                    Ok((major, minor, patch))
268	                } else {
269	                    Ok((major.checked_add(1).ok_or_else(overflow)?, 0, 0))
270	                }
271	            }
272	            Severity::None => unreachable!("callers return early on Severity::None before reaching this point"),
273	        }
274	    } else {
275	        match severity {
276	            Severity::Major => Ok((major.checked_add(1).ok_or_else(overflow)?, 0, 0)),
277	            Severity::Minor => Ok((major, minor.checked_add(1).ok_or_else(overflow)?, 0)),
278	            Severity::Patch => Ok((major, minor, patch.checked_add(1).ok_or_else(overflow)?)),
279	            Severity::None => unreachable!("callers return early on Severity::None before reaching this point"),
280	        }
281	    }
282	}
