  71	    ws: &Workspace<'_, R, D>,
  72	    inference: &I,
  73	    opts: &VersionOptions,
  74	) -> Result<VersionPlan, GraphError> {
  75	    let base_versions = ws.base_versions()?;
  76	    let tags = ws.tags()?;
  77	
  78	    let pre_path = ws.root.join(ws.config.pre_json_path());
  79	    let (pre_state, pre_json_original_text) = if pre_path.exists() {
  80	        let text =
  81	            std::fs::read_to_string(&pre_path).map_err(|e| GraphError::PreJsonRead { message: e.to_string() })?;
  82	        let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
  83	        (Some(state), Some(text))
  84	    } else {
  85	        (None, None)
  86	    };
  87	
  88	    let mut agg = aggregate(
  89	        &ws.graph,
  90	        &ws.identity,
  91	        &ws.config,
  92	        ws.git_access(),
