 134	
 135	    let outcome = run_cascade(input)?;
 136	
 137	    let mut bumps = Vec::new();
 138	    let mut changelog_writes = Vec::new();
 139	
 140	    // PERF-006: build a map once so each lookup inside the loop is O(1)
 141	    // instead of O(N) (the previous packages().find() call).
 142	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
 143	
 144	    for (id, &sev) in &outcome.severities {
 145	        if sev == Severity::None {
 146	            continue;
 147	        }
 148	        let pkg = pkg_map.get(id).copied().unwrap();
 149	        let from = base_versions.get(id).cloned().ok_or_else(|| {
