 387	/// True when `HEAD`'s tree still has an unconsumed changeset file, read from the commit, not the working tree.
 388	fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
 389	    ws: &Workspace<'_, R, D>,
 390	    head: &str,
 391	) -> Result<bool, GraphError> {
 392	    let dir = ws.config.changesets_dir.to_string_lossy();
 393	    let spec = format!("{head}:{dir}");
 394	    if !head_object_exists(ws, &spec)? {
 395	        // The changesets directory didn't exist at HEAD (e.g. the first `version` run); nothing left pending.
 396	        return Ok(false);
 397	    }
 398	    let output = ws
 399	        .runner
 400	        .run("git", &["ls-tree", "--name-only", &spec], &ws.root)
 401	        .map_err(GraphError::Command)?;
 402	    if !output.success() {
 403	        return Ok(false);
 404	    }
 405	    Ok(output.stdout.lines().any(|name| {
 406	        let name = name.trim();
 407	        name.ends_with(".md") && name != "README.md"
 408	    }))
 409	}
