 411	/// The version a canonical manifest declared at `head`, or `None` if it didn't exist there or can't be parsed.
 412	fn manifest_version_at<R: CommandRunner, D: DependencyResolver>(
 413	    ws: &Workspace<'_, R, D>,
 414	    head: &str,
 415	    path: &std::path::Path,
 416	) -> Result<Option<callisto_model::Version>, GraphError> {
 417	    let Ok(format) = callisto_model::ManifestFormat::from_path(path) else {
 418	        return Ok(None);
 419	    };
 420	    let path_str = path.to_string_lossy();
 421	    let spec = format!("{head}:{path_str}");
 422	    if !head_object_exists(ws, &spec)? {
 423	        return Ok(None);
 424	    }
 425	    let output = ws
 426	        .runner
 427	        .run("git", &["show", &spec], &ws.root)
 428	        .map_err(GraphError::Command)?;
 429	    if !output.success() {
 430	        return Ok(None);
 431	    }
 432	    let identity = match callisto_manifests::read_identity(format, &output.stdout, path) {
 433	        Ok(identity) => identity,
 434	        Err(_) => return Ok(None),
 435	    };
 436	    let Some(callisto_manifests::VersionSource::Literal(raw)) = identity.version else {
 437	        return Ok(None);
 438	    };
 439	    match callisto_model::Version::parse(&raw, format.ecosystem().version_grammar()) {
 440	        Ok(version) => Ok(Some(version)),
 441	        Err(_) => Ok(None),
 442	    }
 443	}
