 445	/// Platform manifest version writes and owner `optionalDependencies` pin updates
 446	/// for every owner with a target version in `targets`. Sources: each owner's
 447	/// attached platform manifests, plus `[[fixed-group]]`
 448	/// platform members.
 449	pub(crate) fn platform_version_writes<R: CommandRunner, D: DependencyResolver>(
 450	    ws: &Workspace<'_, R, D>,
 451	    targets: &std::collections::BTreeMap<callisto_model::PackageId, callisto_model::Version>,
 452	) -> Result<(Vec<PlatformWrite>, Vec<crate::plan::OptionalDepUpdate>), GraphError> {
 453	    let open_ctx = OpenContext::for_workspace_root(&ws.root);
 454	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
 455	
 456	    let mut members: Vec<(&callisto_model::PackageId, &std::path::Path, &str)> = Vec::new();
 457	    for pkg in ws.graph.packages() {
 458	        members.extend(
 459	            ws.identity
 460	                .attached_platforms(pkg)
 461	                .map(|(name, path)| (&pkg.id, path, name)),
 462	        );
 463	    }
 464	    for group in ws.config.groups.fixed.values() {
 465	        for member in group.members(GroupMemberKind::PlatformManifest) {
 466	            if let GroupMember::PlatformManifest { owner, path, name, .. } = member {
 467	                members.push((owner, path, name));
 468	            }
 469	        }
 470	    }
 471	
 472	    let mut seen = HashSet::new();
 473	    let mut platform_writes = Vec::new();
 474	    let mut optional_dep_map: std::collections::BTreeMap<std::path::PathBuf, Vec<(String, callisto_model::Version)>> =
 475	        std::collections::BTreeMap::new();
 476	    for (owner, path, name) in members {
 477	        let Some(to) = targets.get(owner) else {
 478	            continue;
 479	        };
 480	        if !seen.insert(path) {
 481	            continue;
 482	        }
 483	        let fmt = callisto_model::ManifestFormat::from_path(path)?;
 484	        let decl = callisto_model::ManifestDecl::new(path, ManifestRole::Canonical, fmt)?;
 485	        let handle = open(&decl, &open_ctx)?;
 486	        let current = handle.current_version()?;
 487	        platform_writes.push(PlatformWrite {
 488	            manifest: path.to_path_buf(),
 489	            version: to.clone(),
 490	            from: current,
 491	        });
 492	
 493	        // A dual-manifest owner declares its platforms in package.json, not Cargo.toml.
 494	        for owner_decl in pkg_map.get(owner).into_iter().flat_map(|p| p.canonical_manifests()) {
 495	            let owner_fmt = callisto_model::ManifestFormat::from_path(&owner_decl.path)?;
 496	            let owner_manifest_decl =
 497	                callisto_model::ManifestDecl::new(owner_decl.path.clone(), ManifestRole::Canonical, owner_fmt)?;
 498	            // Cached: owner manifest is shared across every platform target under it.
 499	            let owner_handle = crate::manifest_cache::open_cached(&ws.manifest_cache, &owner_manifest_decl, &open_ctx)?;
 500	            if owner_handle
 501	                .iter_dependencies()
 502	                .any(|dep| dep.kind == callisto_model::DepKind::Optional && dep.name == name)
 503	            {
 504	                optional_dep_map
 505	                    .entry(owner_decl.path.clone())
 506	                    .or_default()
 507	                    .push((name.to_string(), to.clone()));
 508	                break;
 509	            }
 510	        }
 511	    }
 512	    let optional_dep_updates = optional_dep_map
 513	        .into_iter()
 514	        .map(|(manifest, updates)| crate::plan::OptionalDepUpdate { manifest, updates })
 515	        .collect();
 516	    Ok((platform_writes, optional_dep_updates))
 517	}
