  70	pub fn plan_version<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
  71	    ws: &Workspace<'_, R, D>,
  72	    inference: &I,
  73	    opts: &VersionOptions,
  74	) -> Result<VersionPlan, GraphError> {
  75	    let base_versions = ws.base_versions()?;
  76	    let tags = ws.tags()?;
  77	
  78	    let pre_path = ws.root.join(ws.config.pre_json_path());
  79	    let (pre_state, pre_json_original_text) = if pre_path.exists() {
  80	        let text =
  81	            std::fs::read_to_string(&pre_path).map_err(|e| GraphError::PreJsonRead { message: e.to_string() })?;
  82	        let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
  83	        (Some(state), Some(text))
  84	    } else {
  85	        (None, None)
  86	    };
  87	
  88	    let mut agg = aggregate(
  89	        &ws.graph,
  90	        &ws.identity,
  91	        &ws.config,
  92	        ws.git_access(),
  93	        tags,
  94	        &base_versions,
  95	        pre_state.as_ref(),
  96	        inference,
  97	    )?;
  98	
  99	    // For PreMode::Exit, inject a synthetic Patch severity for every package
 100	    // that is currently at a pre-release version. This triggers bump_target
 101	    // (which in Exit mode calls versioning.bump on the pre-release, stripping
 102	    // the tag and finalizing to stable) even when no pending changeset files
 103	    // exist on disk — they were consumed and deleted during the pre-release phase
 104	    // and their stems recorded in pre.json.
 105	    if let Some(ref pre) = pre_state {
 106	        if pre.mode == callisto_model::format::PreMode::Exit {
 107	            for (id, ver) in &base_versions {
 108	                if ver.is_prerelease() {
 109	                    agg.severities.entry(id.clone()).or_insert(Severity::Patch);
 110	                    agg.reasons
 111	                        .entry(id.clone())
 112	                        .or_insert(BumpReason::PreRelease { tag: pre.tag.clone() });
 113	                }
 114	            }
 115	        }
 116	    }
 117	
 118	    let input = CascadeInput {
 119	        graph: &ws.graph,
 120	        groups: &ws.config.groups,
 121	        cfg: &ws.config.cascade,
 122	        seed: &agg.severities,
 123	        reasons: &agg.reasons,
 124	        named_by: &agg.named_by,
