 248	    let is_pre_mode = pre_state
 249	        .as_ref()
 250	        .map(|s| s.mode == callisto_model::format::PreMode::Pre)
 251	        .unwrap_or(false);
 252	    // The "no pending changesets" warning fires only when no changeset, new or already recorded, is active this run.
 253	    let nothing_pending = if is_pre_mode {
