   311	/// Refuses when the workspace shows the signature of a crashed `version` run: a manifest's on-disk version has
   312	/// moved past `HEAD` while either a changeset is still pending there, or (outside an active pre-release cycle) the
   313	/// manifest is staged but uncommitted. Continuing would compound the drift instead of surfacing it.
   314	pub fn check_partial_run<R: CommandRunner, D: DependencyResolver>(ws: &Workspace<'_, R, D>) -> Result<(), GraphError> {
   315	    let Ok(head) = ws.git_access().head_sha() else {
   316	        return Ok(());
   317	    };
   318	    let head = head.as_str();
   319	
   320	    // A pre-release cycle legitimately reruns `version` uncommitted; the staged-manifest check is scoped past it.
   321	    let in_pre_release_cycle = ws.root.join(ws.config.pre_json_path()).exists();
   322	
   323	    let pending = head_has_pending_changeset(ws, head)?
   324	        || (!in_pre_release_cycle && any_canonical_manifest_staged_uncommitted(ws)?);
   325	    if !pending {
   326	        return Ok(());
   327	    }
   328	
   329	    let base_versions = ws.base_versions()?;
   330	    for pkg in ws.graph.packages() {
   331	        let Some(disk) = base_versions.get(&pkg.id) else {
   332	            continue;
   333	        };
   334	        for decl in pkg.canonical_manifests() {
   335	            let Some(head_version) = manifest_version_at(ws, head, &decl.path)? else {
   336	                continue;
   337	            };
   338	            if *disk != head_version {
   339	                return Err(GraphError::PartialVersionRun {
   340	                    path: decl.path.clone(),
   341	                    disk: disk.clone(),
   342	                    head: head_version,
   343	                });
   344	            }
   345	        }
   346	    }
   347	
   348	    Ok(())
   349	}
