   375	/// Whether `<rev>:<path>` names an object; `--quiet` keeps a missing path from printing to stderr.
   376	fn head_object_exists<R: CommandRunner, D: DependencyResolver>(
   377	    ws: &Workspace<'_, R, D>,
   378	    spec: &str,
   379	) -> Result<bool, GraphError> {
   380	    let output = ws
   381	        .runner
   382	        .run("git", &["rev-parse", "--verify", "--quiet", spec], &ws.root)
   383	        .map_err(GraphError::Command)?;
   384	    Ok(output.success())
   385	}
