        .and_then(|rest| rest.strip_suffix('"'))
        .unwrap()
        .to_string()
}

fn status_package<'a>(status: &'a serde_json::Value, id: &str) -> Option<&'a serde_json::Value> {
    status["packages"].as_array()?.iter().find(|pkg| pkg["package"] == id)
}

